const PERK_COLORS = { 1: { c: "#4aa8ff", dark: "#0d2340", row: "#0f2238", glow: "rgba(74,168,255,0.7)" }, 2: { c: "#b46cf2", dark: "#2a1240", row: "#22123a", glow: "rgba(180,108,242,0.7)" }, 3: { c: "#ffc93a", dark: "#3a2a06", row: "#2e2408", glow: "rgba(255,200,60,0.95)" } };
