function perkOnTurnStart(state, idx) {
  handAgesTick(state.players[idx]); // Cyber-Golem gets cheaper each turn it waits in the hand
  if (state.tutorial) return; // no perks in the tutorial
  const p = state.players[idx], opp = state.players[perkOther(idx)];
  p.board.forEach((m) => { if (m.stone || m.noAttack) m.canAttack = false; }); // Stone Blocks and Basic64 never attack
  // Multiplicating Abomination: survived the opponent's next turn -> one copy
  [...p.board].forEach((m) => {
    if (!m.multiplyIn) return;
    m.multiplyIn -= 1;
    if (m.multiplyIn > 0) return;
    // every Abomination (copies too) copies itself each time it survives the opponent's turn
    m.multiplyIn = 1;
    if (p.board.length < 6 && m.hp > 0) { const cp = makeTokenInstance(m.name, false); cp.multiplyIn = 1; p.board.push(cp); log(state, `${m.name} makes a copy of itself.`); }
  });
  (p.perks || []).forEach((x) => {
    if (x.depleted) return;
    const def = PERK_BY_ID[x.id];
    if (x.id === "leftovers") { if (p.maxMana >= 10) { p.perkManaBonus = Math.max(0, (p.perkManaBonus || 0) - 1); perkDeplete(x); log(state, `${def.name} runs out.`); } return; }
    if (x.rounds !== undefined) { x.rounds -= 1; if (x.rounds <= 0) perkDeplete(x); return; }
    if (x.id === "healingwave" || x.id === "selfpres" || x.id === "randomness") {
      if (x.id === "healingwave") healPlayer(state, idx, 4);
      if (x.id === "selfpres") { p.armor += 5; p.matchStats.armorGained += 5; }
      if (x.id === "randomness") { const pool = CARD_DB.filter((c) => c.rarity === "epic"); perkAddToHand(state, idx, pool[Math.floor(Math.random() * pool.length)].id); }
      log(state, `${def.name} triggers.`);
      x.ticks -= 1; if (x.ticks <= 0) perkDeplete(x);
    } else if (x.id === "copycat") {
      const pool = [...new Set(opp.playedCards || [])];
      const options = pickRandomN(pool, 3);
      if (options.length) perkQueueDiscover(state, { playerIdx: idx, options, mode: "hand", title: "Copycat", sub: "Pick one to add to your hand." });
      log(state, `${def.name} triggers.`);
      perkDeplete(x);
    } else if (x.id === "sneaky") {
      const options = pickRandomN(opp.hand, 3);
      if (options.length) perkQueueDiscover(state, { playerIdx: idx, options, mode: "destroyHand", title: "Sneaky Bastard", sub: "Pick a card to destroy in your opponent's hand." });
      log(state, `${def.name} triggers.`);
      perkDeplete(x);
    } else if (x.id === "stonehenge") {
      opp.board = opp.board.filter((m) => !m.stone);
      perkDeplete(x);
    }
  });
  // offer the next perk level this player has reached
  p.perkOffered = p.perkOffered || {};
  for (const level of [1, 2, 3]) {
    if (p.maxMana < PERK_LEVEL_AP[level] || p.perkOffered[level]) continue;
    p.perkOffered[level] = true;
    const blocker = perkActive(opp, "partyblocker");
    if (blocker) {
      perkDeplete(blocker);
      log(state, `${p.hero}'s perk is blocked by ${PERK_BY_ID.partyblocker.name}.`, true);
      break;
    }
    const options = pickRandomN(PERKS.filter((d) => d.level === level), 3).map((d) => d.id);
    state.pendingPerk = { playerIdx: idx, level, options, startedAt: Date.now() };
    break;
  }
}

function perkChoose(state, idx, perkId) {
  const pend = state.pendingPerk;
  if (pend && pend.playerIdx === idx && pend.options.includes(perkId) && pend.then) {
    // VHS Tape Recording: after this pick comes a second one, one level up
    const nextLevel = pend.then;
    perkChooseOne(state, idx, perkId);
    if (state.winner === null || state.winner === undefined) state.pendingPerk = { playerIdx: idx, level: nextLevel, options: pickRandomN(PERKS.filter((d) => d.level === nextLevel), 3).map((d) => d.id), startedAt: Date.now() };
    return;
  }
  perkChooseOne(state, idx, perkId);
}
function perkChooseOne(state, idx, perkId) {
  const pend = state.pendingPerk;
  if (!pend || pend.playerIdx !== idx || !pend.options.includes(perkId)) return;
  state.pendingPerk = null;
  perkApply(state, idx, perkId);
}
// Gives player `idx` the perk (a perk choice, or a random Surprise from Compass when `via` is set).
function perkApply(state, idx, perkId, via) {
  const def = PERK_BY_ID[perkId];
  const p = state.players[idx], oppIdx = perkOther(idx), opp = state.players[oppIdx];
  const x = { id: perkId, level: def.level, depleted: false, revealed: !def.surprise };
  p.perks = [...(p.perks || []), x];
  log(state, via ? `${p.hero} gets a random Surprise.` : def.surprise ? `${p.hero} picks a Surprise perk.` : `${p.hero} picks the perk ${def.name}.`);
  switch (perkId) {
    case "juice": p.maxHealth = 35; healPlayer(state, idx, 5); perkDeplete(x); break;
    case "leftovers": p.perkManaBonus = (p.perkManaBonus || 0) + 1; if (p.maxMana < 10) p.mana += 1; break;
    case "nocountry": x.rounds = 5; break;
    case "healingwave": healPlayer(state, idx, 4); x.ticks = 2; break;
    case "armorheist": { const a = opp.armor || 0; opp.armor = 0; p.armor += a; p.matchStats.armorGained += a; perkDeplete(x); break; }
    case "tinkerer": x.uses = 2; break;
    case "freezemines": x.rounds = 5; break;
    case "toxicmines": x.rounds = 2; break;
    case "stonehenge": {
      const keep = pickRandomN(opp.board.filter((m) => !m.stone), 1);
      shotWrap(state, idx, null, () => opp.board.forEach((m) => { if (!keep.includes(m)) destroyMinion(m); }));
      removeDeadMinions(state);
      for (let i = 0; i < 5 && opp.board.length < 6; i++) { const b = makeTokenInstance("Stone Block", false); b.stone = true; opp.board.push(b); }
      break;
    }
    case "freebie": {
      const pool = CARD_DB.filter((c) => c.type === "spell" && c.cost >= 5 && !c.reward);
      perkQueueDiscover(state, { playerIdx: idx, options: pickRandomN(pool, 3).map((c) => c.id), mode: "playFree", title: "Freebie", sub: "Pick one to play right now for free." });
      perkDeplete(x); break;
    }
    case "demotivator": opp.perkManaPenalty = (opp.perkManaPenalty || 0) + 1; break;
    case "fairsquare": perkSetMaxHealth(state, 25); perkDeplete(x); break;
    case "lucky7": {
      const pool = CARD_DB.filter((c) => c.type === "minion" && c.cost === 7 && !c.needsTarget);
      perkQueueDiscover(state, { playerIdx: idx, options: pickRandomN(pool, 3).map((c) => c.id), mode: "playFree", title: "Lucky Number 7", sub: "Pick a minion to play right now for free." });
      perkDeplete(x); break;
    }
    case "miniapoc":
      if (miniApocWorks(opp)) { opp.board.forEach(destroyMinion); log(state, `${def.name} triggers.`); }
      else log(state, `${def.name} has no effect.`);
      perkDeplete(x); break;
    case "investor": x.uses = 2; break;
    case "secondwind": {
      p.armor += 10; p.matchStats.armorGained += 10;
      perkShuffleIn(p, pickRandomN(p.playedCards || [], 10));
      perkDeplete(x); break;
    }
    case "smell": perkShuffleIn(p, pickRandomN(opp.playedCards || [], 5)); drawCard(state, idx); perkDeplete(x); break;
    case "timetofinish": perkSetMaxHealth(state, 15); perkDeplete(x); break;
    case "randomness": { const pool = CARD_DB.filter((c) => c.rarity === "epic"); perkAddToHand(state, idx, pool[Math.floor(Math.random() * pool.length)].id); x.ticks = 4; break; }
    case "hangover": state.players.forEach((pl) => pl.board.forEach((m) => { m.atk = 1; m.hp = 1; m.maxHp = 1; })); perkDeplete(x); break;
    case "doubleagents": break; // watched after every action (perkAfterAction)
    case "selfpres": p.armor += 5; p.matchStats.armorGained += 5; x.ticks = 2; break;
    default: break;
  }
  removeDeadMinions(state);
  checkWin(state);
}

// Returns true when the card's own effect must be skipped (Sabotage).
function perkOnPlayCard(state, idx, card, minion) {
  const p = state.players[idx], oppIdx = perkOther(idx), opp = state.players[oppIdx];
  p.playedCards = [...(p.playedCards || []), card.id];
  if (card.type === "minion") p.maxMinionCostPlayed = Math.max(p.maxMinionCostPlayed || 0, card.cost);
  let skip = false;
  // the player's own perks
  const dem = (opp.perks || []).find((x) => x.id === "demotivator" && !x.depleted);
  if (dem && card.cost >= 6 && (p.perkManaPenalty || 0) > 0) { p.perkManaPenalty -= 1; perkDeplete(dem); log(state, `${p.hero} shakes off ${PERK_BY_ID.demotivator.name}.`); }
  const inv = perkActive(p, "investor");
  if (inv && card.rarity === "unique" && card.cost >= 8) {
    const pool = CARD_DB.filter((c) => c.rarity === "unique" && !c.reward);
    perkAddToHand(state, idx, pool[Math.floor(Math.random() * pool.length)].id);
    perkReveal(state, inv);
    inv.uses -= 1; if (inv.uses <= 0) perkDeplete(inv);
  }
  if (minion) {
    const tink = perkActive(p, "tinkerer");
    if (tink) { minion.shielded = true; tink.uses -= 1; if (tink.uses <= 0) perkDeplete(tink); }
  }
  // the opponent's perks (traps)
  if (card.type === "spell") {
    const sab = perkActive(opp, "sabotage");
    if (sab && card.cost <= 5) { perkReveal(state, sab); perkDeplete(sab); skip = true; }
  }
  skip = trapOnPlayCard(state, idx, card, minion, skip);
  if (minion) {
    const pun = perkActive(opp, "punisher");
    if (pun && card.cost <= 3) { perkReveal(state, pun); shotWrap(state, oppIdx, null, () => dealDamageToPlayer(state, idx, 3)); }
    const nc = perkActive(opp, "nocountry");
    const ch = perkActive(opp, "charismatic");
    if (nc && card.cost <= 3) { perkReveal(state, nc); shotWrap(state, oppIdx, null, () => destroyMinion(minion)); skip = true; }
    else if (ch && card.cost <= 5 && opp.board.length < 6) {
      perkReveal(state, ch); perkDeplete(ch);
      p.board = p.board.filter((m) => m !== minion);
      minion.canAttack = false;
      opp.board.push(minion);
      cardFx(state, { kind: "moved", owner: oppIdx, cardId: minion.cardId, name: minion.name, atk: minion.atk, hp: minion.hp });
      skip = true;
    }
  }
  if (card.trap && !skip) trapArm(state, idx, card);
  return skip;
}

/* ---------- win-reward items ---------- */
// Using the item: it waits (like a perk) until it triggers. VHS Tape Recording offers two perks instead.
function trapArm(state, idx, card) {
  const p = state.players[idx];
  if (card.trap === "vhs") {
    state.pendingPerk = { playerIdx: idx, level: 2, options: pickRandomN(PERKS.filter((d) => d.level === 2), 3).map((d) => d.id), startedAt: Date.now(), then: 3 };
    return;
  }
  const def = PERK_BY_ID[card.trap];
  if (!def) return;
  p.perks = [...(p.perks || []), { id: card.trap, level: "item", depleted: false, revealed: !def.surprise }];
}
function trapFire(state, x) { perkReveal(state, x); perkDeplete(x); }
// Puts a token on `idx`'s side (if there's room) and returns it - its effect happens either way.
function trapSummon(state, idx, name, extra) {
  const p = state.players[idx];
  const m = Object.assign(makeTokenInstance(name, false), extra || {});
  if (p.board.length < 6) { p.board.push(m); log(state, `${p.hero} summons ${name}.`); }
  return m;
}
// Lab Rat: hits one of the enemy's working hands (same rules as an aimed shot at a hand)
function trapHitHand(state, foeIdx, dmg, srcName) {
  const foe = state.players[foeIdx];
  const hs = handsOf(foe);
  const live = [0, 1].filter((i) => hs[i].hp > 0);
  if (!live.length) return;
  const hi = live[Math.floor(Math.random() * live.length)];
  const part = hi === 0 ? "left" : "right";
  const h = hs[hi];
  h.hp = Math.max(0, h.hp - dmg);
  log(state, `${srcName} hits ${foe.hero}'s ${part} hand for ${dmg}.`);
  if (h.hp <= 0) {
    log(state, `${foe.hero}'s ${part} hand is crippled!`, true);
    const lost = h.item;
    if (h.item) { const c = findCard(h.item); h.item = null; if (c) log(state, `${foe.hero}'s ${c.name} is destroyed.`); }
    state.handEvent = { id: Date.now() + "-" + Math.floor(Math.random() * 1e6), playerIdx: foeIdx, hand: part, item: lost || null };
  }
}
// Player `idx` just played `card`: the opponent's items may spring. Returns the new `skip`.
function trapOnPlayCard(state, idx, card, minion, skip) {
  const p = state.players[idx], oppIdx = perkOther(idx), opp = state.players[oppIdx];
  if (minion) {
    p.mtCount = p.mtTurn === state.turnNumber ? (p.mtCount || 0) + 1 : 1;
    p.mtTurn = state.turnNumber;
    const cake = perkActive(opp, "t_cake");
    if (cake && card.cost >= 6 && minion.hp > 0) {
      trapFire(state, cake);
      log(state, `${minion.name} turns into Erika.`);
      Object.assign(minion, { cardId: null, name: "Erika", atk: 4, hp: 4, maxHp: 4, keywords: [], shielded: false, onDamage: null });
      skip = true; // no Entrance
    }
    const egg = perkActive(opp, "t_egg");
    if (egg) {
      trapFire(state, egg);
      if (opp.board.length < 6) { opp.board.push(makeMinionInstance(card.id, false)); log(state, `${opp.hero} gets a copy of ${card.name}.`); }
    }
    const tank = perkActive(opp, "t_tank");
    if (tank && card.cost >= 7) {
      trapFire(state, tank);
      const t = trapSummon(state, oppIdx, "Pocket Tank");
      const targets = p.board.filter((m) => m.hp > 0);
      if (targets.length) {
        const v = targets[Math.floor(Math.random() * targets.length)];
        log(state, `${t.name} shoots ${v.name} for 7.`);
        shotWrap(state, oppIdx, null, () => damageMinion(state, v, 7, idx));
      }
    }
    // Poisoned Food counts every minion the opponent plays after it was set; it goes off once the 3rd has been played
    const food = perkActive(opp, "t_food");
    if (food) { food.seen = (food.seen || 0) + 1; if (food.seen >= 3) food.ready = true; }
    const v2 = perkActive(opp, "t_v2");
    if (v2 && p.mtCount >= 2) {
      trapFire(state, v2);
      trapSummon(state, oppIdx, "Basic64 Computer", { noAttack: true, v2: true });
    }
  } else if (card.type === "spell") {
    const rat = perkActive(opp, "t_rat");
    if (rat) {
      trapFire(state, rat);
      const ratM = trapSummon(state, oppIdx, "Lab Rat", { ignoreTaunt: true });
      // the rat runs over and bites a hand in person (only when it found room on the board)
      if (opp.board.includes(ratM)) {
        const fx = meleeFx(state, oppIdx, ratM, GIMP_FIRST);
        fx.hand = true;
        state.gimpFx = fx;
      }
      trapHitHand(state, idx, 7, "Lab Rat");
    }
  }
  return skip;
}
// Player `idx` used their hero ability (Multiplicator counts these).
function perkOnPower(state, idx) {
  if (state.tutorial) return;
  const oppIdx = perkOther(idx), opp = state.players[oppIdx];
  const mu = perkActive(opp, "t_mult");
  if (!mu) return;
  mu.count = (mu.count || 0) + 1;
  if (mu.count >= 2) { trapFire(state, mu); trapSummon(state, oppIdx, "Multiplicating Abomination", { multiplyIn: 2 }); }
}
// Gimp Calling (checked after every action, once the 7 damage is in)
function trapGimp(state, idx) {
  const p = state.players[idx], foeIdx = perkOther(idx), foe = state.players[foeIdx];
  const g = perkActive(p, "t_gimp");
  if (!g || !g.fire) return;
  trapFire(state, g);
  const gimp = trapSummon(state, idx, "Gimp", { undyingTurn: state.turnNumber });
  // the client plays the attacks one by one (see gimpPlan)
  const fx = meleeFx(state, idx, gimp, GIMP_FIRST);
  state.gimpFx = fx;
  [...foe.board].forEach((m) => { // the enemy side only
    if (m.hp <= 0) return;
    fx.targets.push(m.uid); fx.before[m.uid] = m.hp;
    damageMinion(state, m, gimp.atk, foeIdx);
    if (m.atk > 0) damageMinion(state, gimp, m.atk, idx, false);
    if (gimp.hp < 1) gimp.hp = 1;
    fx.gimpHp.push(gimp.hp);
  });
  meleeHero(state, fx, gimp, idx);
  log(state, `Gimp attacks ${foe.hero}'s minions and hero.`);
}

function perkOnTurnEnd(state, idx) {
  const p = state.players[idx], opp = state.players[perkOther(idx)];
  const res = perkActive(p, "resourceful");
  if (res && p.mana === 0) { p.armor += 1; p.matchStats.armorGained += 1; log(state, `${PERK_BY_ID.resourceful.name} triggers.`); }
}

function perkOnHeroDamage(state, idx, amount) {
  const p = state.players[idx];
  const gimp = perkActive(p, "t_gimp");
  if (gimp && !gimp.fire && amount > 0) { gimp.dmg = (gimp.dmg || 0) + amount; if (gimp.dmg >= 7) gimp.fire = true; }
  const fm = perkActive(p, "freezemines");
  if (fm && (amount === 1 || amount === 2)) {
    perkReveal(state, fm);
    shotWrap(state, idx, null, () => state.players[perkOther(idx)].board.forEach(freezeMinion));
  }
}

function perkOnMinionDies(state, idx, m) {
  const p = state.players[idx];
  if (m.v2 && p.hero === "Cyborg" && !p.powerUpgrade) { p.powerUpgrade = true; log(state, `${p.hero}'s hero ability is upgraded.`); }
  const r = perkActive(p, "resurrection");
  if (r && m.cardId) { perkShuffleIn(p, [m.cardId]); perkReveal(state, r); perkDeplete(r); }
}

// After every action: Toxic Minefield and Double Agents watch the board.
function perkAfterAction(state) {
  state.players.forEach(handAgesSync);
  if (state.tutorial) return;
  state.players.forEach((p, idx) => {
    trapGimp(state, idx);
    const pf = perkActive(p, "t_food");
    const enemy = state.players[perkOther(idx)];
    if (pf && pf.ready) {
      trapFire(state, pf);
      trapSummon(state, idx, "Dodgy Chef");
      const hit = [...enemy.board];
      shotWrap(state, idx, null, () => hit.forEach((m) => damageMinion(state, m, 3, perkOther(idx))));
      hit.forEach((m) => { if (m.hp > 0 && !m.keywords.includes("Toxic")) m.keywords.push("Toxic"); });
      log(state, `Dodgy Chef poisons ${enemy.hero}'s minions.`);
    }
    const da = perkActive(p, "doubleagents");
    const foe = state.players[perkOther(idx)];
    const alive = foe.board.filter((m) => m.hp > 0 && !m.stone && !m.__dying);
    if (da && alive.length >= 4 && p.board.length < 6) {
      const moving = pickRandomN(alive, Math.min(2, 6 - p.board.length));
      foe.board = foe.board.filter((m) => !moving.includes(m));
      moving.forEach((m) => { m.canAttack = false; p.board.push(m); cardFx(state, { kind: "moved", owner: idx, cardId: m.cardId, name: m.name, atk: m.atk, hp: m.hp }); });
      perkReveal(state, da); perkDeplete(da);
      log(state, `${moving.map((m) => m.name).join(" and ")} switch sides.`);
    }
    const tm = perkActive(p, "toxicmines");
    const opp = state.players[perkOther(idx)];
    if (tm && opp.board.length >= 3) {
      let changed = false;
      shotWrap(state, idx, null, () => opp.board.forEach((m) => { if (!m.keywords.includes("Toxic")) { m.keywords.push("Toxic"); changed = true; if (SHOT) SHOT.toxic.push({ uid: m.uid }); } }));
      if (changed) perkReveal(state, tm);
    }
  });
}

// Resolves a perk card choice (Copycat, Freebie, Lucky Number 7, Sneaky Bastard). Returns false for normal Merchant picks.
function perkResolveDiscover(state, idx, cardId) {
  const d = state.pendingDiscover;
  if (!d || !d.mode) return false;
  const p = state.players[idx], opp = state.players[perkOther(idx)];
  const c = findCard(cardId);
  if (d.mode === "hand") { addCardToHand(state, idx, c.name); log(state, `${p.hero} chooses ${c.name}.`); }
  else if (d.mode === "playFree") perkPlayFree(state, idx, c);
  else if (d.mode === "summon") {
    if (p.board.length < 6) { p.board.push(makeMinionInstance(cardId, c.keywords.includes("Charge"))); log(state, `${p.hero} chooses ${c.name}.`); }
  } else if (d.mode === "destroyHand") {
    const i = opp.hand.indexOf(cardId);
    if (i !== -1) { opp.hand.splice(i, 1); log(state, `${p.hero} destroys ${c.name} in ${opp.hero}'s hand.`); cardFx(state, { kind: "handDestroyed", owner: perkOther(idx), cardId }); }
  }
  return true;
}

// Freebie / Lucky Number 7: the chosen card is played straight away at no cost (no target needed), Entrance included.
function perkPlayFree(state, idx, c) {
  const p = state.players[idx];
  let minion = null;
  if (c.type === "minion") {
    if (p.board.length >= 6) { log(state, `${c.name} has no room on the table.`); return; }
    minion = makeMinionInstance(c.id, c.keywords.includes("Charge"));
    p.board.push(minion);
  }
  if (!c.hero) p.matchStats.neutralCardsPlayed += 1;
  if (c.rarity === "epic") p.matchStats.epicCardsPlayed += 1;
  if (c.rarity === "unique") p.matchStats.uniqueCardsPlayed += 1;
  p.lastCardPlayed = c.id;
  log(state, `${p.hero} plays ${c.name} for free.`);
  const skip = perkOnPlayCard(state, idx, c, minion);
  // an item that needs a target (Grenade) is fired at a random enemy: a minion or the hero
  let chosen = null;
  if (c.needsTarget) {
    const foeIdx = perkOther(idx), foe = state.players[foeIdx];
    const pool = [...foe.board.filter((m) => m.hp > 0).map((m) => ({ type: "minion", uid: m.uid, playerIdx: foeIdx, name: m.name })), { type: "hero", playerIdx: foeIdx, name: foe.hero }];
    const t = pool[Math.floor(Math.random() * pool.length)];
    chosen = { type: t.type, uid: t.uid, playerIdx: t.playerIdx };
    log(state, `${c.name} hits ${t.name}.`);
  }
  // shots from a card a perk plays for you leave from your HANDS
  if (c.effect && !skip) shotWrap(state, idx, c, () => applyEffects(state, c.effect, idx, idx, chosen, true, minion));
  removeDeadMinions(state);
  checkWin(state);
}
// Mini Apocalypse only works while the opponent hasn't played a minion costing 3 AP or more.
function miniApocWorks(opp) { return (opp.maxMinionCostPlayed || 0) < 3; }

// CPU: picks a perk (or a perk card) right away.
function aiPerkAction(state, cpuIdx) {
  if (state.pendingPerk && state.pendingPerk.playerIdx === cpuIdx) {
    const o = state.pendingPerk.options;
    return { type: "choosePerk", perkId: o[Math.floor(Math.random() * o.length)] };
  }
  if (state.pendingDiscover && state.pendingDiscover.playerIdx === cpuIdx) {
    const best = [...state.pendingDiscover.options].sort((a, b) => (findCard(b).cost || 0) - (findCard(a).cost || 0))[0];
    return { type: "discoverChoice", cardId: best };
  }
  return null;
}

/* ---------- interface ---------- */
function PerkIcon({ level, surprise, size = 16 }) {
  const col = PERK_COLORS[level] || PERK_COLORS[1];
  const glow = level === 3 ? `drop-shadow(0 0 4px ${col.glow})` : undefined;
  if (surprise) {
    return (
      <svg viewBox="-12 -12 24 24" width={size} height={size} style={{ display: "block", flexShrink: 0, filter: glow }}>
        <circle r="10.5" fill={col.dark} stroke={col.c} strokeWidth="2.2" />
        <text x="0" y="5.2" textAnchor="middle" fontSize="15" fontWeight="900" fill={col.c} fontFamily="Arial, sans-serif">?</text>
      </svg>
    );
  }
  return <span style={{ display: "inline-flex", filter: glow }}><DxTrefoil size={size} color={col.c} dark={col.dark} /></span>;
}
// "Perks: ..." line on a hero panel. The opponent sees a Surprise perk only as its icon.
// Hovering, clicking or tapping an icon shows that perk and how long it still works.
function perkTimeLeft(x) {
  if (x.rounds !== undefined) return x.rounds === 1 ? tr("Last round") : tr("{n} rounds left", { n: x.rounds });
  if (x.ticks !== undefined) return x.ticks === 1 ? tr("1 more round") : tr("{n} more rounds", { n: x.ticks });
  if (x.uses !== undefined) return x.uses === 1 ? tr("1 use left") : tr("{n} uses left", { n: x.uses });
  if (x.id === "leftovers") return tr("Until your AP reaches 10");
  return tr("Until it triggers");
}
function PerkStrip({ player, owner, size = 13, style, label = true }) {
  const live = (player.perks || []).filter((x) => !x.depleted && x.level !== "item");
  const [tip, setTip] = useState(null); // { i, rect, pinned }
  const stripRef = useRef(null);
  const mode = useDisplay().mode;
  const themed = isThemedMode(mode), pixel = mode === "pixel";
  useEffect(() => {
    if (!tip || !tip.pinned) return undefined;
    const away = (e) => { const t = e.target; if (!((stripRef.current && stripRef.current.contains(t)) || (t.closest && t.closest(".dx-perk-tip")))) setTip(null); };
    document.addEventListener("pointerdown", away, true);
    return () => document.removeEventListener("pointerdown", away, true);
  }, [tip && tip.pinned, tip && tip.i]);
  const show = (e, i, pinned) => setTip({ i, rect: e.currentTarget.getBoundingClientRect(), pinned });
  const x = tip && live[tip.i];
  const def = x && PERK_BY_ID[x.id];
  const hidden = def && def.surprise && !owner && !x.revealed;
  let bubble = null;
  if (x && def) {
    const col = PERK_COLORS[def.level];
    const W = Math.min(300, window.innerWidth - 16);
    const left = Math.max(8, Math.min(window.innerWidth - W - 8, tip.rect.left + tip.rect.width / 2 - W / 2));
    const below = tip.rect.top < 180;
    bubble = createPortal(
      <div className="dx-perk-tip" data-kwtap="1" onClick={(e) => e.stopPropagation()}
        style={{ position: "fixed", left, width: W, boxSizing: "border-box", zIndex: 950, ...(below ? { top: tip.rect.bottom + 8 } : { bottom: window.innerHeight - tip.rect.top + 8 }),
          padding: "10px 12px", borderRadius: pixel ? 0 : 10, border: `2px solid ${col.c}`, textAlign: "left", lineHeight: 1.35, fontSize: 13,
          background: themed ? `linear-gradient(180deg, ${col.row}, rgba(12,11,10,0.97))` : "#fff", color: themed ? "#efe7d8" : "#111",
          boxShadow: themed ? `0 10px 26px rgba(0,0,0,0.6), 0 0 18px ${col.glow.replace(/0\.\d+\)$/, "0.3)")}` : "3px 3px 0 rgba(0,0,0,0.25)",
          fontFamily: themed ? (pixel ? DX_PIXEL_FONT : DX_FONT) : FONT, pointerEvents: tip.pinned ? "auto" : "none" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <PerkIcon level={def.level} surprise={!!def.surprise} size={22} />
          <div style={{ fontWeight: 900, color: themed ? col.c : "#111", textTransform: themed ? "uppercase" : "none", letterSpacing: themed && !pixel ? "0.04em" : 0 }}>{hidden ? tr("Surprise") : perkNameL(def)}</div>
        </div>
        <div style={{ marginTop: 5, opacity: 0.92 }}>{hidden ? tr(def.level === "item" ? "A hidden item. It shows itself when it triggers." : "Hidden until it triggers.") : <PerkDesc def={def} />}</div>
        {!hidden && <div style={{ marginTop: 6, fontWeight: 800, color: themed ? "#8dffb0" : "#1a7a3a" }}>⏳ {perkTimeLeft(x)}</div>}
      </div>,
      document.body
    );
  }
  return (
    <span ref={stripRef} style={{ display: "inline-flex", alignItems: "center", gap: 3, whiteSpace: "nowrap", ...style }}>
      {label && <span style={{ opacity: 0.85 }}>{tr("Perks:")}</span>}
      {live.length === 0 ? <span style={{ opacity: 0.7 }}>{tr("None")}</span> : live.map((p, i) => (
        <span key={i} className="dx-perk-ico" style={{ display: "inline-flex", cursor: "help", padding: 2, margin: -2 }}
          onMouseEnter={(e) => { if (!(tip && tip.pinned)) show(e, i, false); }}
          onMouseLeave={() => setTip((t) => (t && !t.pinned ? null : t))}
          onPointerDown={(e) => e.stopPropagation()}
          onClick={(e) => { e.stopPropagation(); e.preventDefault(); if (tip && tip.pinned && tip.i === i) setTip(null); else show(e, i, true); }}>
          <PerkIcon level={p.level} surprise={!!PERK_BY_ID[p.id].surprise} size={size} />
        </span>
      ))}
      {bubble}
    </span>
  );
}
// Wraps a hero panel: right-click or long-press opens the perk list.
function PerkPressArea({ player, owner, children }) {
  const [open, setOpen] = useState(false);
  const timer = useRef(null), fired = useRef(false);
  const start = () => { fired.current = false; timer.current = setTimeout(() => { fired.current = true; setOpen(true); }, 550); };
  const cancel = () => { if (timer.current) { clearTimeout(timer.current); timer.current = null; } };
  return (
    <div style={{ display: "contents" }}
      onContextMenu={(e) => { e.preventDefault(); setOpen(true); }}
      onTouchStart={start} onTouchEnd={cancel} onTouchMove={cancel} onMouseDown={(e) => { if (e.button === 0) start(); }} onMouseUp={cancel} onMouseLeave={cancel}
      onClickCapture={(e) => { if (fired.current) { fired.current = false; e.stopPropagation(); e.preventDefault(); } }}>
      {children}
      {open && <PerkDetailModal player={player} owner={owner} onClose={() => setOpen(false)} />}
    </div>
  );
}
function PerkDesc({ def, dark }) {
  if (def.cardId) return <span>{cardTextL(findCard(def.cardId))}</span>; // an item: its own card text
  return (
    <span>
      {def.surprise && <><DxKw info={{ kind: "kw", id: "Surprise" }} text={tr("Surprise")} />{". "}</>}
      {tr(def.desc)}
    </span>
  );
}
function PerkDetailModal({ player, owner, onClose }) {
  const mode = useDisplay().mode;
  const themed = isThemedMode(mode), pixel = mode === "pixel";
  const all = player.perks || [];
  const rows = [];
  [1, 2, 3].forEach((level) => { const xs = all.filter((p) => p.level === level); if (xs.length) xs.forEach((x) => rows.push({ level, x })); else rows.push({ level, x: null }); });
  const box = themed
    ? { background: "rgba(20,17,14,0.97)", color: "#efe7d8", border: pixel ? "3px solid #0a0a06" : "1px solid #4a3c30", borderRadius: pixel ? 0 : 12, fontFamily: pixel ? DX_PIXEL_FONT : DX_FONT }
    : { background: "#fff", color: "#111", border: "3px solid #000", borderRadius: 10, fontFamily: FONT };
  return createPortal(
    <div data-tut-popup="1" data-kwtap="1" onClick={(e) => { e.stopPropagation(); onClose(); }} style={{ position: "fixed", inset: 0, zIndex: 420, background: "rgba(0,0,0,0.6)", display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }}>
      <div onClick={(e) => e.stopPropagation()} style={{ ...box, width: "min(460px, 100%)", padding: 18, boxShadow: "0 18px 50px rgba(0,0,0,0.6)" }}>
        <div style={{ fontWeight: 800, fontSize: 17, marginBottom: 12, textTransform: themed ? "uppercase" : "none", letterSpacing: themed && !pixel ? "0.08em" : 0 }}>
          {tr("Perks")} — {player.displayName || heroL(player.hero)}
        </div>
        {rows.map(({ level, x }, ri) => {
          const col = PERK_COLORS[level];
          const def = x && PERK_BY_ID[x.id];
          const hidden = def && def.surprise && !owner && !x.revealed;
          return (
            <div key={ri} style={{ position: "relative", display: "flex", gap: 12, alignItems: "center", padding: "10px 12px", marginTop: 8, borderRadius: pixel ? 0 : 8, overflow: "hidden",
              background: themed ? col.row : `color-mix(in srgb, ${col.c} 14%, #fff)`, border: `1px solid ${themed ? col.c + "66" : col.c}` }}>
              {def ? <PerkIcon level={level} surprise={!!def.surprise} size={30} /> : <span style={{ width: 30, height: 30, borderRadius: "50%", border: `2px dashed ${col.c}88`, flexShrink: 0 }} />}
              <div style={{ minWidth: 0, fontSize: 13, lineHeight: 1.35 }}>
                <div style={{ fontWeight: 800, color: themed ? col.c : "#111", fontSize: 13.5 }}>
                  {level === "item" ? tr("Item") : tr("Level {n} perk", { n: level })}{def ? " — " + (hidden ? tr("Surprise") : perkNameL(def)) : " — " + tr("None")}
                </div>
                {def && <div style={{ marginTop: 2, opacity: 0.92 }}>{hidden ? tr("Hidden until it triggers.") : <PerkDesc def={def} />}</div>}
              </div>
              {x && x.depleted && (
                <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", pointerEvents: "none", background: "rgba(0,0,0,0.25)" }}>
                  <span style={{ fontWeight: 900, fontSize: 26, letterSpacing: "0.2em", color: "rgba(120,255,60,0.72)", textShadow: "0 0 12px rgba(120,255,60,0.8)", transform: "rotate(-6deg)", fontFamily: themed ? (pixel ? DX_PIXEL_FONT : DX_DISPLAY_FONT) : FONT }}>{tr("DEPLETED")}</span>
                </div>
              )}
            </div>
          );
        })}
        <div style={{ fontSize: 11.5, opacity: 0.7, marginTop: 12 }}>{tr("Right-click or long-press a hero to see their perks.")}</div>
        <div style={{ textAlign: "center", marginTop: 12 }}>
          <button onClick={onClose} className={themed ? "dx-btn" : undefined} style={themed ? { fontSize: 16 } : { fontFamily: FONT, padding: "6px 18px", border: "2px solid #000", background: "#000", color: "#fff", borderRadius: 4, cursor: "pointer" }}>{tr("Close")}</button>
        </div>
      </div>
    </div>,
    document.body
  );
}

// Banner over the enemy hero row: "Opponent picked the perk ..." (or a hidden Surprise perk),
// and again when one of their Surprise perks springs. Closed with the cross.
function PerkAnnounce({ state, myIdx }) {
  const mode = useDisplay().mode;
  const themed = isThemedMode(mode), pixel = mode === "pixel";
  const opp = state.players[myIdx === 0 ? 1 : 0];
  const snap = (opp.perks || []).map((x) => x.id + ":" + (x.revealed ? 1 : 0));
  const prev = useRef(null);
  const [msg, setMsg] = useState(null); // {key, x, kind: "pick" | "reveal"}
  useEffect(() => {
    const before = prev.current;
    prev.current = snap;
    if (!before) return;
    const perks = opp.perks || [];
    for (let i = perks.length - 1; i >= 0; i--) {
      const x = perks[i], was = before[i];
      if (!was) { setMsg({ key: Date.now(), x, kind: "pick" }); return; }
      if (was.endsWith(":0") && x.revealed) { if (!PERK_BY_ID[x.id].surprise) setMsg({ key: Date.now(), x, kind: "reveal" }); return; } // Surprises get SurprisePop
    }
  }, [snap.join("|")]);
  // it covers the enemy hero, so it also goes away by itself after a while, or as soon as you tap somewhere else
  useEffect(() => {
    if (!msg) return undefined;
    const t = setTimeout(() => setMsg(null), 12000);
    const away = (e) => { if (Date.now() - msg.key > 1200 && !(e.target.closest && e.target.closest(".dx-perk-banner"))) setMsg(null); };
    document.addEventListener("pointerdown", away, true);
    return () => { clearTimeout(t); document.removeEventListener("pointerdown", away, true); };
  }, [msg ? msg.key : null]);
  if (!msg) return null;
  const def = PERK_BY_ID[msg.x.id];
  const col = PERK_COLORS[def.level];
  // on the illustrated tables the banner hangs just under the enemy hero, so the "?" over the hero stays visible
  const heroEl = document.querySelector('[data-dx-hero="opp"]');
  const hr = heroEl ? heroEl.getBoundingClientRect() : null;
  const bw = Math.min(600, window.innerWidth - 12);
  const place = hr ? { left: Math.max(6, Math.min(window.innerWidth - bw - 6, hr.left + hr.width / 2 - bw / 2)), right: "auto", width: bw, top: hr.bottom + 10, margin: 0 } : {};
  const hidden = msg.kind === "pick" && def.surprise;
  const isItem = def.level === "item";
  const title = msg.kind === "reveal"
    ? tr("Surprise! {perk} triggers.", { perk: perkNameL(def) })
    : isItem ? (hidden ? tr("Opponent set a Surprise item") : tr("Opponent set the item {item}", { item: perkNameL(def) }))
    : hidden ? tr("Opponent picked a Surprise perk") : tr("Opponent picked the perk {perk}", { perk: tr(def.name) });
  return createPortal(
    <div key={msg.key} className="dx-perk-banner" style={{ position: "fixed", left: 6, right: 6, top: 6, margin: "0 auto", zIndex: 360, maxWidth: 760, boxSizing: "border-box", ...place,
      display: "flex", gap: 14, alignItems: "center", padding: "12px 46px 12px 14px", borderRadius: pixel ? 0 : 12, color: themed ? "#f3ecdf" : "#111",
      background: themed ? `linear-gradient(100deg, ${col.row} 0%, rgba(14,12,10,0.97) 75%)` : `color-mix(in srgb, ${col.c} 16%, #fff)`,
      border: `2px solid ${col.c}`, boxShadow: themed ? `0 10px 30px rgba(0,0,0,0.6), 0 0 26px ${col.glow.replace(/0\.\d+\)$/, "0.35)")}` : "3px 3px 0 rgba(0,0,0,0.25)",
      fontFamily: themed ? (pixel ? DX_PIXEL_FONT : DX_FONT) : FONT, animation: "dxPerkIn 0.45s cubic-bezier(.2,.8,.2,1) both" }}>
      <style>{"@keyframes dxPerkIn { 0% { opacity: 0; transform: translateY(-16px) scale(0.96); } 100% { opacity: 1; transform: none; } }"}</style>
      <PerkIcon level={def.level} surprise={!!def.surprise} size={38} />
      <div data-kwtap="1" style={{ minWidth: 0, textAlign: "left" }}>
        <div style={{ fontWeight: 900, fontSize: 15.5, color: themed ? col.c : "#111", textTransform: themed ? "uppercase" : "none", letterSpacing: themed && !pixel ? "0.05em" : 0 }}>{title}</div>
        <div style={{ fontSize: 13, lineHeight: 1.35, marginTop: 3, opacity: 0.92 }}>
          {isItem ? tr("Item") : tr("Level {n} perk", { n: def.level })} · {hidden ? tr("Hidden until it triggers.") : <PerkDesc def={def} />}
        </div>
      </div>
      <button type="button" aria-label={tr("Close")} onClick={() => setMsg(null)}
        style={{ position: "absolute", right: 8, top: "50%", transform: "translateY(-50%)", width: 32, height: 32, border: `1px solid ${col.c}`, borderRadius: pixel ? 0 : "50%", background: "rgba(0,0,0,0.25)", color: themed ? "#f3ecdf" : "#111", fontSize: 18, lineHeight: "28px", cursor: "pointer", padding: 0 }}>×</button>
    </div>,
    document.body
  );
}

// A Surprise going off (either side): its card bursts out of the "?" over the hero, stays a few seconds, then slowly fades.
const SX_POP_HOLD = 3400, SX_POP_OUT = 1500;
function SurprisePop({ state, myIdx }) {
  const mode = useDisplay().mode;
  const themed = isThemedMode(mode), pixel = mode === "pixel";
  const snap = state.players.map((p) => (p.perks || []).map((x) => x.id + ":" + (x.revealed ? 1 : 0)).join(",")).join("|");
  const prev = useRef(null);
  const rects = useRef({});
  const [queue, setQueue] = useState([]);
  const ref = useRef(null);
  // remember where each "?" badge is: it can disappear in the same moment its last Surprise goes off
  useEffect(() => {
    const look = () => ["me", "opp"].forEach((side) => { const b = document.querySelector(`[data-dx-hero="${side}"] .sx-badge`); if (b) { const r = b.getBoundingClientRect(); if (r.width) rects.current[side] = r; } });
    look(); const t = setInterval(look, 400);
    return () => clearInterval(t);
  }, []);
  useEffect(() => {
    const before = prev.current;
    prev.current = state.players.map((p) => (p.perks || []).map((x) => x.id + ":" + (x.revealed ? 1 : 0)));
    if (!before) return;
    const fresh = [];
    state.players.forEach((p, idx) => (p.perks || []).forEach((x, i) => {
      const was = before[idx] && before[idx][i];
      const def = PERK_BY_ID[x.id];
      if (def && def.surprise && x.revealed && was && was.endsWith(":0")) fresh.push({ key: Date.now() + Math.random(), def, side: idx === myIdx ? "me" : "opp" });
    }));
    if (fresh.length) setQueue((q) => [...q, ...fresh]);
  }, [snap]);
  const cur = queue[0] || null;
  useEffect(() => {
    if (!cur) return undefined;
    const el = ref.current;
    const next = () => setQueue((q) => q.slice(1));
    if (!el || !el.animate) { const t = setTimeout(next, SX_POP_HOLD); return () => clearTimeout(t); }
    // grows out of the badge
    const hero = document.querySelector(`[data-dx-hero="${cur.side}"]`);
    const b = rects.current[cur.side] || (hero && hero.getBoundingClientRect());
    const pr = el.getBoundingClientRect();
    const ox = b ? b.left + b.width / 2 - (pr.left + pr.width / 2) : 0, oy = b ? b.top + b.height / 2 - (pr.top + pr.height / 2) : 0;
    const badge = document.querySelector(`[data-dx-hero="${cur.side}"] .sx-badge`);
    if (badge && badge.animate) badge.animate([{ scale: "1" }, { scale: "1.6", filter: "brightness(2)" }, { scale: "1" }], { duration: 450, easing: "ease-out" });
    const up = cur.side === "me" ? 10 : -10;
    const a = el.animate([
      { transform: `translate(${ox}px,${oy}px) scale(0.12)`, opacity: 0 },
      { transform: "translate(0,0) scale(1.05)", opacity: 1, offset: 0.06 },
      { transform: "translate(0,0) scale(1)", opacity: 1, offset: 0.09 },
      { transform: "translate(0,0) scale(1)", opacity: 1, offset: SX_POP_HOLD / (SX_POP_HOLD + SX_POP_OUT) },
      { transform: `translate(0,${-up}px) scale(0.98)`, opacity: 0 },
    ], { duration: SX_POP_HOLD + SX_POP_OUT, easing: "ease-in-out", fill: "both" });
    a.onfinish = next;
    return () => { a.onfinish = null; a.cancel(); };
  }, [cur ? cur.key : null]);
  if (!cur) return null;
  const def = cur.def, col = PERK_COLORS[def.level] || PERK_COLORS.item;
  const hero = document.querySelector(`[data-dx-hero="${cur.side}"]`);
  const hr = hero ? hero.getBoundingClientRect() : null;
  const bw = Math.min(380, window.innerWidth - 16);
  // the hero sits in the middle with its panels around it, so the card opens just under the enemy hero / just above yours
  let left, pos;
  {
    left = hr ? Math.max(8, Math.min(window.innerWidth - bw - 8, hr.left + hr.width / 2 - bw / 2)) : (window.innerWidth - bw) / 2;
    pos = cur.side === "opp" ? { top: hr ? hr.bottom + 8 : 80 } : { bottom: hr ? window.innerHeight - hr.top + 8 : 160 };
  }
  const font = themed ? (pixel ? DX_PIXEL_FONT : DX_FONT) : FONT;
  return createPortal(
    <div ref={ref} key={cur.key} className="dx-surprise-pop" data-kwtap="1" onClick={() => setQueue((q) => q.slice(1))}
      style={{ position: "fixed", left, width: bw, ...pos, zIndex: 365, boxSizing: "border-box", padding: "12px 16px 14px", cursor: "pointer", opacity: 0,
        borderRadius: pixel ? 0 : 14, fontFamily: font, color: themed ? "#f3ecdf" : "#111", textAlign: "center",
        background: themed ? `radial-gradient(ellipse at 50% 0%, ${col.row} 0%, rgba(14,12,10,0.97) 70%)` : "#fff",
        border: `2px solid ${themed ? "#ffd24a" : "#000"}`,
        boxShadow: themed ? `0 12px 34px rgba(0,0,0,0.65), 0 0 28px rgba(255,200,40,0.35), inset 0 0 18px ${col.glow.replace(/0\.\d+\)$/, "0.25)")}` : "3px 3px 0 rgba(0,0,0,0.25)" }}>
      <div style={{ fontFamily: themed && !pixel ? DX_DISPLAY_FONT : font, fontWeight: 900, fontSize: 26, letterSpacing: themed && !pixel ? "0.08em" : 0, lineHeight: 1, color: themed ? "#ffd24a" : "#b35a00",
        textShadow: themed ? "0 0 14px rgba(255,190,40,0.8), 0 2px 0 #5a3a00" : "none", transform: themed && !pixel ? "skewX(-8deg)" : undefined }}>{tr("SURPRISE!")}</div>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 8, marginTop: 8 }}>
        <PerkIcon level={def.level} surprise size={24} />
        <div style={{ fontWeight: 900, fontSize: 16, color: themed ? col.c : "#111", textTransform: themed ? "uppercase" : "none", letterSpacing: themed && !pixel ? "0.04em" : 0 }}>{perkNameL(def)}</div>
      </div>
      <div style={{ fontSize: 13.5, lineHeight: 1.4, marginTop: 6, opacity: 0.93 }}><PerkDesc def={def} dark={themed} /></div>
    </div>,
    document.body
  );
}

function PerkChoice(props) {
  return <><PerkAnnounce state={props.state} myIdx={props.myIdx} /><SurprisePop state={props.state} myIdx={props.myIdx} /><PerkChoiceModal {...props} /><CardFxHost state={props.state} myIdx={props.myIdx} /><ShotFxHost state={props.state} myIdx={props.myIdx} /><HealFxHost state={props.state} myIdx={props.myIdx} /></>;
}
// The perk choice. Shown to the player whose turn it is; the other player sees a small note.
function PerkChoiceModal({ state, myIdx, onAction }) {
  const mode = useDisplay().mode;
  const themed = isThemedMode(mode), pixel = mode === "pixel";
  const pend = state.pendingPerk;
  const [now, setNow] = useState(Date.now());
  const [picked, setPicked] = useState(null);
  useEffect(() => { setPicked(null); }, [pend ? pend.startedAt : null]);
  useEffect(() => {
    if (!pend || pend.playerIdx !== myIdx || state.winner !== null) return undefined;
    const t = setInterval(() => setNow(Date.now()), 250);
    const left = Math.max(0, (pend.startedAt || Date.now()) + PERK_PICK_MS - Date.now());
    const auto = setTimeout(() => onAction({ type: "choosePerk", perkId: pend.options[Math.floor(Math.random() * pend.options.length)] }), left + 150);
    return () => { clearInterval(t); clearTimeout(auto); };
  }, [pend ? pend.startedAt : null, pend ? pend.playerIdx : null, myIdx, state.winner]);
  if (!pend || state.winner !== null) return null;
  const col = PERK_COLORS[pend.level];
  if (pend.playerIdx !== myIdx) {
    return createPortal(
      <div style={{ position: "fixed", left: "50%", top: 12, transform: "translateX(-50%)", zIndex: 300, padding: "8px 16px", borderRadius: pixel ? 0 : 999, background: themed ? "rgba(20,17,14,0.92)" : "#fff", color: themed ? "#efe7d8" : "#111", border: `2px solid ${col.c}`, fontFamily: themed ? (pixel ? DX_PIXEL_FONT : DX_FONT) : FONT, fontSize: 13, display: "flex", gap: 8, alignItems: "center", pointerEvents: "none" }}>
        <PerkIcon level={pend.level} size={16} />{tr("Opponent is choosing a perk…")}
      </div>, document.body);
  }
  const secs = Math.max(0, Math.ceil(((pend.startedAt || now) + PERK_PICK_MS - now) / 1000));
  const vw = typeof window !== "undefined" ? window.innerWidth : 1000;
  const narrow = vw < 640;
  return createPortal(
    <div data-kwtap="1" data-tut-popup="1" className={themed ? dxRootClass(mode) : undefined} style={{ position: "fixed", inset: 0, zIndex: 380, background: "rgba(4,4,6,0.82)", display: "flex", alignItems: "center", justifyContent: "center", padding: 14, fontFamily: themed ? (pixel ? DX_PIXEL_FONT : DX_FONT) : FONT, color: themed ? "#efe7d8" : "#111" }}>
      <div style={{ width: "min(860px, 100%)", textAlign: "center", ...(themed ? {} : { background: "#fff", border: "3px solid #000", borderRadius: 10, padding: 16 }) }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 10 }}>
          <PerkIcon level={pend.level} size={28} />
          <div style={{ fontWeight: 900, fontSize: narrow ? 20 : 28, letterSpacing: themed && !pixel ? "0.12em" : 0, textTransform: "uppercase", color: themed ? col.c : "#111" }}>{tr("Choose a Level {n} perk", { n: pend.level })}</div>
        </div>
        <div style={{ fontSize: 13, opacity: 0.8, marginTop: 6 }}>{tr("{n}s left — then one is picked at random.", { n: secs })}</div>
        <div style={{ display: "flex", flexDirection: narrow ? "column" : "row", gap: 12, marginTop: 16, alignItems: "stretch" }}>
          {pend.options.map((id) => {
            const def = PERK_BY_ID[id];
            return (
              <button key={id} type="button" className="dx-perk-opt" disabled={!!picked}
                onClick={() => { setPicked(id); onAction({ type: "choosePerk", perkId: id }); }}
                style={{ flex: 1, textAlign: "left", cursor: "pointer", font: "inherit", color: "inherit", padding: narrow ? "10px 12px" : "16px 16px 18px",
                  display: "flex", flexDirection: narrow ? "row" : "column", gap: narrow ? 12 : 10, alignItems: narrow ? "center" : "flex-start",
                  background: themed ? `linear-gradient(180deg, ${col.row}, rgba(10,9,8,0.95))` : `color-mix(in srgb, ${col.c} 12%, #fff)`,
                  border: `2px solid ${picked === id ? "#fff" : col.c}`, borderRadius: pixel ? 0 : 12, boxShadow: themed ? `0 0 22px ${col.glow.replace(/0\.\d+\)$/, "0.25)")}` : "2px 2px 0 rgba(0,0,0,0.2)" }}>
                <PerkIcon level={def.level} surprise={!!def.surprise} size={narrow ? 30 : 40} />
                <span>
                  <span style={{ display: "block", fontWeight: 900, fontSize: narrow ? 15 : 17, color: themed ? col.c : "#111", textTransform: themed ? "uppercase" : "none", letterSpacing: themed && !pixel ? "0.06em" : 0 }}>{tr(def.name)}</span>
                  <span style={{ display: "block", fontSize: narrow ? 12.5 : 13.5, lineHeight: 1.4, marginTop: 4, opacity: 0.92 }}><PerkDesc def={def} /></span>
                  {id === "miniapoc" && (() => {
                    const ok = miniApocWorks(state.players[perkOther(pend.playerIdx)]);
                    return <span style={{ display: "inline-block", marginTop: 8, padding: "3px 9px", borderRadius: pixel ? 0 : 8, fontSize: 12, fontWeight: 900, letterSpacing: "0.04em",
                      color: ok ? "#06210d" : "#fff", background: ok ? "#5dff8f" : "#c0392b", boxShadow: themed && ok ? "0 0 10px rgba(93,255,143,0.6)" : "none" }}>
                      {ok ? "✓ " + tr("Will work now") : "✗ " + tr("Won't work — they already played a 3+ AP minion")}</span>;
                  })()}
                </span>
              </button>
            );
          })}
        </div>
      </div>
    </div>,
    document.body
  );
}
/* =========================================================================
   HANDS (item slots) & AIMED SHOTS
   - Every hero has a left and a right hand, 7 HP each.
   - Items (spells) are equipped into a free hand for 1 AP; an equipped item then costs 1 AP less.
     Equipped items are not in the card hand, so they don't count toward the 10-card limit.
   - A hand at 0 HP is crippled and drops its item. One crippled hand: items +1 AP.
     Both crippled: items are played straight from the card hand at +2 AP.
   - Aimed shot: once per round, 1 AP, aim at head / left hand / right hand. The next minion
     attack on the enemy hero is the aimed shot. Head: +1/+2/+3 damage (60/30/10%).
     Hand: the damage also hits that hand.
   ========================================================================= */
const HAND_HP = 7;
const HAND_NAMES = ["left", "right"];
const NEON = "#39ff6a";
function handsOf(p) {
  if (!p.hands) p.hands = [{ hp: HAND_HP, item: null }, { hp: HAND_HP, item: null }];
  return p.hands;
}
function handsView(p) { return (p && p.hands) || [{ hp: HAND_HP, item: null }, { hp: HAND_HP, item: null }]; }
function crippledCount(p) { return handsView(p).filter((h) => h.hp <= 0).length; }
function bothHandsCrippled(p) { return crippledCount(p) >= 2; }
function freeHandIdx(p) { return handsView(p).findIndex((h) => h.hp > 0 && !h.item); }
// cost of using an item that is already in a hand
function slotUseCost(p, card) { return Math.max(0, card.cost - 1) + crippledCount(p); }
// what tapping a card in the card hand costs right now (an item: equipping it - unless both hands are crippled)
function handCardCost(p, card, state, handIdx) {
  if (card.type !== "spell") return dynMinionCost(state, p, card, handIdx);
  return bothHandsCrippled(p) ? card.cost + 2 : 1;
}
function handCardBlocked(p, card) { return card.type === "spell" && !bothHandsCrippled(p) && freeHandIdx(p) === -1; }
// "1+4" on an item card: 1 AP to equip + what it then costs to use
function itemCostLabel(p, card) {
  if (!card || card.type !== "spell") return null;
  if (bothHandsCrippled(p)) return String(card.cost + 2);
  return `1+${slotUseCost(p, card)}`;
}
const aimPartLabel = (part) => (part === "head" ? tr("Head") : part === "left" ? tr("Left hand") : tr("Right hand"));

// why an aimed shot can't be taken right now (null = it can)
function aimBlockReason(state, idx, part) {
  const p = state.players[idx], foe = state.players[idx === 0 ? 1 : 0];
  if (state.winner !== null || state.turn !== idx) return "It's not your turn.";
  if (foe.board.some((m) => m.keywords.includes("Taunt"))) return "A Distract minion is guarding the enemy hero.";
  if (!p.board.some((m) => m.canAttack && m.atk > 0 && !isFrozenNow(m))) return "None of your minions can attack right now.";
  if (p.aim) return "You are already aiming.";
  if (p.aimTurn === state.turnNumber) return "Only one aimed shot per round.";
  if (p.mana < 1) return "Not enough AP.";
  if (part && part !== "head" && handsView(foe)[part === "left" ? 0 : 1].hp <= 0) return "That hand is already crippled.";
  return null;
}
const AIM_PICK = "#ff8a2a"; // the picked body part
const AIM_HERO_BLOCKS = ["A Distract minion is guarding the enemy hero.", "None of your minions can attack right now."];

/* ----- engine ----- */
function handsHandleAction(state, idx, action) {
  const me = state.players[idx];
  const foe = state.players[idx === 0 ? 1 : 0];
  if (state.turn !== idx) return;
  if (action.type === "equip") {
    const cardId = me.hand[action.handIdx];
    const c = cardId && findCard(cardId);
    if (!c || c.type !== "spell" || me.mana < 1 || bothHandsCrippled(me)) return;
    const hs = handsOf(me);
    let slot = action.slot === 0 || action.slot === 1 ? action.slot : freeHandIdx(me);
    if (slot === -1 || !hs[slot] || hs[slot].item || hs[slot].hp <= 0) slot = freeHandIdx(me);
    if (slot === -1) return;
    me.hand.splice(action.handIdx, 1);
    hs[slot].item = cardId;
    me.mana -= 1;
    log(state, `${me.hero} equips an item.`);
  } else if (action.type === "aim") {
    if (!["head", "left", "right"].includes(action.part)) return;
    if (aimBlockReason(state, idx, action.part)) return;
    me.mana -= 1;
    me.aim = action.part;
    me.aimTurn = state.turnNumber;
    log(state, `${me.hero} takes aim at ${foe.hero}'s ${action.part === "head" ? "head" : action.part + " hand"}.`);
  } else if (action.type === "aimCancel") {
    if (!me.aim) return;
    me.aim = null;
    me.aimTurn = null;
    me.mana += 1;
    log(state, `${me.hero} lowers their aim.`);
  }
}
// a minion of player `idx` just hit the enemy hero: if they were aiming, this was the aimed shot
function aimOnHeroHit(state, idx, atk) {
  const p = state.players[idx];
  if (!p.aim) return;
  const part = p.aim;
  p.aim = null;
  const foeIdx = idx === 0 ? 1 : 0;
  const foe = state.players[foeIdx];
  if (part === "head") {
    const r = Math.random();
    const extra = r < 0.6 ? 1 : r < 0.9 ? 2 : 3;
    dealDamageToPlayer(state, foeIdx, extra);
    log(state, `Headshot! ${atk.name} deals ${extra} extra damage.`);
    return;
  }
  const hi = part === "left" ? 0 : 1;
  const h = handsOf(foe)[hi];
  if (h.hp <= 0) return;
  const dmg = Math.max(0, atk.atk);
  h.hp = Math.max(0, h.hp - dmg);
  log(state, `${atk.name} hits ${foe.hero}'s ${part} hand for ${dmg}.`);
  if (h.hp <= 0) {
    log(state, `${foe.hero}'s ${part} hand is crippled!`, true);
    const lost = h.item;
    if (h.item) {
      const c = findCard(h.item);
      h.item = null;
      if (c) log(state, `${foe.hero}'s ${c.name} is destroyed.`);
    }
    // both players see a banner about it (see HandCrippleBanner)
    state.handEvent = { id: Date.now() + "-" + Math.floor(Math.random() * 1e6), playerIdx: foeIdx, hand: part, item: lost || null };
  }
}

/* ----- CPU ----- */
function aiHandsAction(state, cpuIdx, phase) {
  const me = state.players[cpuIdx];
  const hs = handsView(me);
  if (phase === "use") {
    for (let s = 0; s < 2; s++) {
      const h = hs[s];
      if (!h.item || h.hp <= 0) continue;
      const c = findCard(h.item);
      if (!c || slotUseCost(me, c) > me.mana) continue;
      let chosen = null;
      if (c.needsTarget) { chosen = aiPickTarget(state, cpuIdx, c.needsTarget); if (!chosen) continue; }
      return { type: "playCard", slot: s, chosen };
    }
  } else if (phase === "equip") {
    if (me.mana < 1 || bothHandsCrippled(me)) return null;
    const slot = freeHandIdx(me);
    if (slot === -1) return null;
    const i = me.hand.findIndex((id) => { const c = findCard(id); return c && c.type === "spell"; });
    if (i !== -1) return { type: "equip", handIdx: i, slot };
  }
  return null;
}
function aiAimAction(state, cpuIdx) {
  const me = state.players[cpuIdx];
  const foe = state.players[cpuIdx === 0 ? 1 : 0];
  if (me.aim || aimBlockReason(state, cpuIdx, null)) return null;
  const hs = handsView(foe);
  const ok = [0, 1].filter((i) => hs[i].hp > 0);
  const armed = ok.filter((i) => hs[i].item);
  let part = "head";
  if (armed.length && Math.random() < 0.6) part = HAND_NAMES[armed[0]];
  else if (ok.length && Math.random() < 0.35) part = HAND_NAMES[ok[Math.floor(Math.random() * ok.length)]];
  return { type: "aim", part };
}

/* ----- UI ----- */
function useSkin() {
  const mode = useDisplay().mode;
  const themed = isThemedMode(mode), pixel = mode === "pixel";
  return { mode, themed, pixel, font: themed ? (pixel ? DX_PIXEL_FONT : DX_FONT) : FONT };
}
function HandGlyph({ size = 12, color = "currentColor", crippled }) {
  return (
    <svg width={size} height={size} viewBox="0 0 16 16" style={{ flexShrink: 0, display: "block" }} aria-hidden="true">
      <path d="M4 15 L3.2 8.6 Q3 7.4 4 7.3 Q4.9 7.3 5 8.4 L5.3 9.4 L5.3 2.8 Q5.3 1.8 6.2 1.8 Q7.1 1.8 7.1 2.8 L7.1 7 L7.3 1.6 Q7.3 0.6 8.2 0.6 Q9.1 0.6 9.1 1.6 L9.1 7 L9.4 2.4 Q9.4 1.4 10.3 1.4 Q11.2 1.5 11.2 2.5 L11.1 7.4 L11.6 4.2 Q11.8 3.3 12.6 3.4 Q13.4 3.6 13.3 4.6 L12.6 10.4 Q12.3 13 11 15 Z" fill={color} opacity={crippled ? 0.45 : 1} />
      {crippled && <path d="M2 2 L14 14 M14 2 L2 14" stroke="#ff4a3a" strokeWidth="2.2" strokeLinecap="round" />}
    </svg>
  );
}
function Crosshair({ size = 22, color = NEON }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" aria-hidden="true" style={{ display: "block" }}>
      <circle cx="12" cy="12" r="8" fill="none" stroke={color} strokeWidth="2" />
      <circle cx="12" cy="12" r="2" fill={color} />
      <path d="M12 1 V7 M12 17 V23 M1 12 H7 M17 12 H23" stroke={color} strokeWidth="2" strokeLinecap="round" />
    </svg>
  );
}

// Small "hand HP" text on a hero panel. Tap it to slide up the hands (inventory).
function HandsBadge({ player, api, mine, size = 12, style }) {
  const sk = useSkin();
  const [open, setOpen] = useState(false);
  const hs = handsView(player);
  const enemyAim = api && api.state.players[mine ? (api.myIdx === 0 ? 1 : 0) : api.myIdx].aim;
  const color = sk.themed ? "#d8d2c4" : "#111";
  return (
    <>
      <style>{HANDS_CSS}</style>
      <button type="button" className={"dx-hands-badge" + (sk.themed ? " dx-hands-tile" : "")} title={tr("Hands")} aria-label={tr("Hands")}
        onClick={(e) => { e.stopPropagation(); setOpen(true); }}
        onPointerDown={(e) => e.stopPropagation()}
        style={{ position: "relative", display: "inline-flex", flexDirection: "column", alignItems: "center", gap: size * 0.05, padding: `${size * 0.1}px ${size * 0.42}px ${size * 0.12}px`, margin: 0, cursor: "pointer", font: "inherit", lineHeight: 1, whiteSpace: "nowrap", flexShrink: 0,
          color, background: sk.themed ? "linear-gradient(180deg, rgba(57,255,106,0.12), rgba(4,18,9,0.75))" : "#fff", border: `${sk.pixel ? 3 : 2}px solid ${sk.themed ? NEON : "#111"}`, borderRadius: sk.pixel ? 0 : size * 0.6,
          boxShadow: sk.themed ? (sk.pixel ? "3px 3px 0 rgba(0,0,0,0.6)" : `0 0 ${size * 0.8}px rgba(57,255,106,0.45), inset 0 0 ${size * 0.6}px rgba(57,255,106,0.18)`) : "2px 2px 0 rgba(0,0,0,0.25)", ...style }}>
        <span style={{ fontSize: size * 0.72, fontWeight: 800, letterSpacing: sk.pixel ? 0 : "0.14em", textTransform: "uppercase", color: sk.themed ? NEON : "#111", opacity: 0.95 }}>{tr("Hands")} ▴</span>
        <span style={{ display: "flex", alignItems: "flex-end", gap: size * 0.5 }}>
          {hs.map((h, i) => (
            <span key={i} style={{ display: "inline-flex", flexDirection: "column", alignItems: "center", gap: size * 0.02 }}>
              <span style={{ display: "inline-flex", transform: i === 0 ? "scaleX(-1)" : "none" }}><HandGlyph size={size * 1.75} color={h.item ? NEON : (sk.themed ? "rgba(232,226,212,0.8)" : "#777")} crippled={h.hp <= 0} /></span>
              <span style={{ fontSize: size * 1.15, fontWeight: 900, color: h.hp <= 0 ? "#ff5a48" : h.hp < HAND_HP ? (sk.themed ? "#ffd24a" : "#b35a00") : (sk.themed ? "#fff" : "#111") }}>{Math.max(0, h.hp)}</span>
            </span>
          ))}
        </span>
        {enemyAim && <span title={tr("Aimed at: {part}", { part: aimPartLabel(enemyAim) })} className="dx-aim-warn" style={{ position: "absolute", top: -size * 0.55, right: -size * 0.55, display: "inline-flex", background: "#1a0605", borderRadius: "50%", padding: 1 }}><Crosshair size={size * 1.1} color="#ff5a48" /></span>}
      </button>
      {open && <HandsSheet player={player} api={api} mine={mine} onClose={() => setOpen(false)} />}
    </>
  );
}

const HANDS_CSS = `
@keyframes dxHandsUp { 0% { transform: translateY(100%); } 100% { transform: none; } }
@keyframes dxAimPulse { 0%,100% { opacity: 1; } 50% { opacity: 0.35; } }
.dx-aim-warn { animation: dxAimPulse 1.1s ease-in-out infinite; }
.dx-hands-tile { transition: transform 0.15s, filter 0.15s; }
.dx-hands-tile:hover { transform: translateY(-1px); filter: brightness(1.25); }
.dx-hands-tile:active { transform: scale(0.96); }
.dx-aim-btn-armed { animation: dxAimPulse 1.4s ease-in-out infinite; }
@keyframes dxWireScan { 0% { transform: translateY(-40px); opacity: 0; } 10% { opacity: 1; } 90% { opacity: 1; } 100% { transform: translateY(300px); opacity: 0; } }
.dx-wire-scan { animation: dxWireScan 3.2s linear infinite; }
.dx-aim-sel { animation: dxAimPulse 1.2s ease-in-out infinite; }
`;

// The slide-up "inventory": both hands, their HP and what they hold.
function HandsSheet({ player, api, mine, onClose }) {
  const sk = useSkin();
  const hs = handsView(player);
  const vw = typeof window !== "undefined" ? window.innerWidth : 1000;
  const vh = typeof window !== "undefined" ? window.innerHeight : 800;
  const narrow = vw < 560;
  const cardScale = Math.max(0.42, Math.min(0.75, (vh * 0.36) / DX_CARD_H, (Math.min(vw, 620) / 2 - 40) / DX_CARD_W));
  const myTurn = api && api.myTurn && mine;
  const cc = crippledCount(player);
  const panel = sk.themed
    ? { background: "linear-gradient(180deg, rgba(26,22,18,0.98), rgba(12,11,10,0.99))", color: "#efe7d8", borderTop: `2px solid ${NEON}88`, boxShadow: `0 -12px 40px rgba(0,0,0,0.7), 0 -2px 24px ${NEON}22` }
    : { background: "#fff", color: "#111", borderTop: "3px solid #000", boxShadow: "0 -6px 0 rgba(0,0,0,0.12)" };
  return createPortal(
    <div data-tut-popup="1" data-kwtap="1" className={sk.themed ? dxRootClass(sk.mode) : undefined} onClick={(e) => { e.stopPropagation(); onClose(); }}
      style={{ position: "fixed", inset: 0, zIndex: 400, background: "rgba(0,0,0,0.45)", display: "flex", alignItems: "flex-end", justifyContent: "center", fontFamily: sk.font }}>
      <style>{HANDS_CSS}</style>
      <div onClick={(e) => e.stopPropagation()} style={{ ...panel, width: "min(640px, 100%)", boxSizing: "border-box", padding: narrow ? "12px 12px 16px" : "16px 20px 20px", borderRadius: sk.pixel ? 0 : "16px 16px 0 0", animation: "dxHandsUp 0.28s cubic-bezier(.2,.8,.2,1) both", maxHeight: "92vh", overflowY: "auto" }}>
        <div data-hands-ap="1" style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 10, marginBottom: 10, padding: "6px 10px", borderRadius: sk.pixel ? 0 : 10, background: sk.themed ? "rgba(70,255,140,0.07)" : "#f2fff5", border: sk.themed ? "1px solid rgba(141,255,176,0.25)" : "2px solid #1a7a3a" }}>
          <span className={sk.themed ? "dx-display" : undefined} style={{ fontSize: 16, fontWeight: 900, color: sk.themed ? "#8dffb0" : "#1a7a3a", whiteSpace: "nowrap", textShadow: sk.themed ? "0 0 8px rgba(141,255,176,0.6)" : "none" }}>{tr("AP left")} {player.mana}/{player.maxMana}</span>
          {sk.themed
            ? <DxDots mana={player.mana} maxMana={player.maxMana} size={12} />
            : <span style={{ letterSpacing: 2, color: "#1a7a3a" }}>{"●".repeat(Math.max(0, player.mana))}<span style={{ color: "#bbb" }}>{"●".repeat(Math.max(0, player.maxMana - player.mana))}</span></span>}
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <HandGlyph size={20} color={sk.themed ? NEON : "#111"} />
          <div style={{ fontWeight: 900, fontSize: 17, textTransform: sk.themed ? "uppercase" : "none", letterSpacing: sk.themed && !sk.pixel ? "0.08em" : 0, flex: 1 }}>
            {mine ? tr("Your hands") : tr("{hero}'s hands", { hero: player.displayName || heroL(player.hero) })}
          </div>
          <button type="button" onClick={onClose} aria-label={tr("Close")} style={{ width: 34, height: 34, borderRadius: sk.pixel ? 0 : "50%", border: `1px solid ${sk.themed ? "#6a5a48" : "#000"}`, background: "transparent", color: "inherit", fontSize: 20, cursor: "pointer", padding: 0 }}>×</button>
        </div>
        <div style={{ display: "flex", gap: narrow ? 10 : 18, marginTop: 12 }}>
          {hs.map((h, i) => {
            const c = h.item ? findCard(h.item) : null;
            const crippled = h.hp <= 0;
            const useCost = c ? slotUseCost(player, c) : 0;
            const canUse = myTurn && c && !crippled && useCost <= player.mana && api.state.winner === null;
            const slotW = DX_CARD_W * cardScale, slotH = DX_CARD_H * cardScale;
            return (
              <div key={i} style={{ flex: 1, minWidth: 0, display: "flex", flexDirection: "column", alignItems: "center", gap: 8 }}>
                <div style={{ fontWeight: 800, fontSize: 14 }}>{i === 0 ? tr("Left hand") : tr("Right hand")}</div>
                <div style={{ display: "flex", gap: 3, alignItems: "center" }} title={tr("{n}/{max} HP", { n: h.hp, max: HAND_HP })}>
                  {Array.from({ length: HAND_HP }).map((_, k) => (
                    <span key={k} style={{ width: 12, height: 8, borderRadius: sk.pixel ? 0 : 2, background: k < h.hp ? (sk.themed ? NEON : "#2ecc71") : (sk.themed ? "rgba(255,255,255,0.12)" : "#ddd"), boxShadow: k < h.hp && sk.themed && !sk.pixel ? `0 0 6px ${NEON}88` : "none" }} />
                  ))}
                  <span style={{ marginLeft: 6, fontSize: 13, fontWeight: 800, color: crippled ? "#ff5a48" : "inherit" }}>{crippled ? tr("Crippled") : `${h.hp}/${HAND_HP}`}</span>
                </div>
                {c && mine ? (
                  sk.themed
                    ? <DeluxeCard card={c} scale={cardScale} costText={String(useCost)} costTone={slotCostTone(player, c, useCost)} dim={!canUse} tilt />
                    : <MiniCard cardId={h.item} costText={String(useCost)} costTone={slotCostTone(player, c, useCost)} disabled={!canUse} />
                ) : c ? (
                  sk.themed ? <DeluxeCardBack w={slotW * 0.8} /> : <div style={{ width: 112, height: 160, border: "2px solid #000", borderRadius: 6, background: "repeating-linear-gradient(45deg,#eee 0 6px,#fff 6px 12px)" }} />
                ) : (
                  <div style={{ width: sk.themed ? slotW : 112, height: sk.themed ? slotH : 160, boxSizing: "border-box", border: `2px dashed ${crippled ? "#ff5a48" : sk.themed ? "rgba(255,255,255,0.25)" : "#999"}`, borderRadius: sk.pixel ? 0 : 12, display: "flex", alignItems: "center", justifyContent: "center", textAlign: "center", padding: 8, fontSize: 13, opacity: 0.8, color: crippled ? "#ff5a48" : "inherit" }}>
                    {crippled ? tr("Crippled — can't hold items") : tr("Empty")}
                  </div>
                )}
                {c && mine && (
                  <button type="button" data-tut="use-slot" className={sk.themed ? "dx-btn dx-btn-go" : undefined} disabled={!canUse}
                    onClick={() => { onClose(); api.useSlot(i); }}
                    style={sk.themed ? { fontSize: 16, minWidth: 120 } : { fontFamily: FONT, padding: "6px 16px", border: "2px solid #000", background: canUse ? "#000" : "#888", color: "#fff", borderRadius: 4, cursor: canUse ? "pointer" : "default" }}>
                    {tr("Use · {n} AP", { n: useCost })}
                  </button>
                )}
              </div>
            );
          })}
        </div>
        <div style={{ fontSize: 12.5, lineHeight: 1.45, opacity: 0.85, marginTop: 14 }}>
          {cc >= 2 ? tr("Both hands are crippled: items are played straight from the hand for +2 AP.")
            : cc === 1 ? tr("A crippled hand makes every item cost +1 AP.")
            : tr("Equip an item from your hand for 1 AP. It then costs 1 AP less to use.")}
        </div>
      </div>
    </div>,
    document.body
  );
}

// Crosshair button next to the enemy hero: opens the aimed shot picker.
function AimButton({ api, size = 44, style }) {
  const sk = useSkin();
  const [open, setOpen] = useState(false);
  if (!api) return null;
  const me = api.me;
  const armed = me.aim;
  const blocked = !!aimBlockReason(api.state, api.myIdx, null) && !armed;
  return (
    <>
      <style>{HANDS_CSS}</style>
      <button type="button" className={"dx-aim-btn" + (armed ? " dx-aim-btn-armed" : "")} title={armed ? tr("Aimed at: {part}", { part: aimPartLabel(armed) }) : tr("Aimed shot")}
        onClick={(e) => { e.stopPropagation(); setOpen(true); }} onPointerDown={(e) => e.stopPropagation()}
        style={{ position: "relative", display: "inline-flex", alignItems: "center", justifyContent: "center", height: size, width: size, padding: 0, cursor: "pointer", font: "inherit", flexShrink: 0,
          borderRadius: sk.pixel ? 0 : size, border: `2px solid ${armed ? "#ff5a48" : sk.themed ? NEON : "#000"}`,
          background: sk.themed ? "rgba(6,20,10,0.85)" : "#fff", boxShadow: sk.themed && !sk.pixel && !blocked ? `0 0 12px ${NEON}66` : "none",
          opacity: blocked && !armed ? 0.45 : 1, color: sk.themed ? "#efe7d8" : "#111", ...style }}>
        <Crosshair size={size * 0.62} color={armed ? "#ff5a48" : sk.themed ? NEON : "#111"} />
        {armed && <span style={{ position: "absolute", left: "50%", top: "100%", transform: "translate(-50%, 3px)", fontSize: Math.max(10, size * 0.22), fontWeight: 800, whiteSpace: "nowrap", padding: "1px 6px", borderRadius: sk.pixel ? 0 : 6, background: "#ff5a48", color: "#fff", lineHeight: 1.3 }}>{aimPartLabel(armed)}</span>}
      </button>
      {open && <AimModal api={api} onClose={() => setOpen(false)} />}
    </>
  );
}

// Neon wireframe body for the aimed shot screen (picture in art/body_wire*, data URIs added by patch_hands.py)
// It is drawn in the SVG's units at x 27.5..172.5, y -10..286; targets are measured on the picture.
const BODY_IMG = { x: 27.5, y: -10, w: 145, h: 296 };
const BODY_PT = (fx, fy) => [BODY_IMG.x + fx * BODY_IMG.w, BODY_IMG.y + fy * BODY_IMG.h];
function wireBody() { return { head: BODY_PT(0.5007, 0.07), left: BODY_PT(0.0762, 0.556), right: BODY_PT(0.9279, 0.556) }; }

function AimModal({ api, onClose }) {
  const sk = useSkin();
  const { state, myIdx, me, opp } = api;
  const armed = me.aim;
  const [part, setPart] = useState(armed || "head");
  const hs = handsView(opp);
  const heroBlock = aimBlockReason(state, myIdx, null);
  const why = armed ? null : aimBlockReason(state, myIdx, part);
  const heroImpossible = AIM_HERO_BLOCKS.includes(heroBlock);
  const vh = typeof window !== "undefined" ? window.innerHeight : 800;
  const figH = Math.max(200, Math.min(380, vh * 0.5));
  const box = sk.themed
    ? { background: "linear-gradient(180deg, rgba(8,22,12,0.98), rgba(5,10,7,0.99))", color: "#e6ffe9", border: `2px solid ${NEON}`, boxShadow: `0 18px 50px rgba(0,0,0,0.7), 0 0 30px ${NEON}44`, borderRadius: sk.pixel ? 0 : 14 }
    : { background: "#fff", color: "#111", border: "3px solid #000", borderRadius: 10 };
  const ink = sk.themed ? NEON : "#111";
  const body = wireBody();
  const sq = (key, cx, cy, r, lx, ly) => {
    const hand = key === "head" ? null : hs[key === "left" ? 0 : 1];
    const dead = hand && hand.hp <= 0;
    const on = part === key;
    const col = dead ? "#ff5a48" : on ? AIM_PICK : ink;
    const c = r * 0.45;
    const br = [[-1, -1], [1, -1], [1, 1], [-1, 1]].map(([dx, dy]) => `M${cx + dx * r} ${cy + dy * r + -dy * c}L${cx + dx * r} ${cy + dy * r}L${cx + dx * r - dx * c} ${cy + dy * r}`).join("");
    const right = lx > cx;
    const label = key === "head" ? tr("Head") : key === "left" ? tr("Left hand") : tr("Right hand");
    return (
      <g key={key} data-tut={"aim-" + key} style={{ cursor: dead || armed ? "default" : "pointer" }} onClick={() => { if (!dead && !armed) setPart(key); }}>
        <rect x={cx - r} y={cy - r} width={r * 2} height={r * 2} fill={on ? "rgba(255,128,32,0.34)" : "rgba(0,0,0,0.01)"} stroke={on ? col : "none"} strokeOpacity="0.9" strokeWidth="1.5" className={on ? "dx-aim-sel" : undefined} />
        <path d={br} fill="none" stroke={col} strokeWidth={on ? 3.6 : 1.8} strokeLinecap="square" style={on && sk.themed && !sk.pixel ? { filter: `drop-shadow(0 0 4px ${AIM_PICK})` } : undefined} />
        {dead && <path d={`M${cx - r * 0.6} ${cy - r * 0.6} L${cx + r * 0.6} ${cy + r * 0.6} M${cx + r * 0.6} ${cy - r * 0.6} L${cx - r * 0.6} ${cy + r * 0.6}`} stroke="#ff5a48" strokeWidth="3" />}
        <path d={`M${cx + (right ? r : -r)} ${cy} L${(cx + lx) / 2} ${ly - 4} L${lx} ${ly - 4}`} fill="none" stroke={col} strokeOpacity={on ? 0.9 : 0.45} strokeWidth="1" />
        <text x={lx} y={ly - 8} textAnchor={right ? "end" : "start"} fontSize="12.5" fontWeight="800" fill={col} fontFamily="inherit" style={{ textTransform: "uppercase" }}>{label}</text>
        {hand && <text x={lx} y={ly + 9} textAnchor={right ? "end" : "start"} fontSize="12" fontWeight="700" fill={col} fillOpacity="0.85" fontFamily="inherit">{dead ? tr("Crippled") : tr("{n}/{max} HP", { n: hand.hp, max: HAND_HP })}</text>}
        {hand && !dead && <text x={lx} y={ly + 24} textAnchor={right ? "end" : "start"} fontSize="11" fontWeight="700" fill={hand.item ? (sk.themed ? "#ffe27a" : "#8a5a00") : col} fillOpacity={hand.item ? 1 : 0.65} fontFamily="inherit">{hand.item ? tr("Holding an item") : tr("Empty")}</text>}
      </g>
    );
  };
  const btn = (primary) => (sk.themed
    ? { className: "dx-btn" + (primary ? " dx-btn-go" : ""), style: { fontSize: 17, minWidth: 130 } }
    : { style: { fontFamily: FONT, padding: "7px 18px", border: "2px solid #000", background: primary ? "#000" : "#fff", color: primary ? "#fff" : "#000", borderRadius: 4, cursor: "pointer" } });
  return createPortal(
    <div data-tut-popup="1" className={sk.themed ? dxRootClass(sk.mode) : undefined} onClick={(e) => { e.stopPropagation(); onClose(); }}
      style={{ position: "fixed", inset: 0, zIndex: 410, background: "rgba(0,0,0,0.65)", display: "flex", alignItems: "center", justifyContent: "center", padding: 12, fontFamily: sk.font }}>
      <div onClick={(e) => e.stopPropagation()} style={{ ...box, width: "min(420px, 100%)", maxHeight: "96vh", overflowY: "auto", boxSizing: "border-box", padding: 16, textAlign: "center" }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 8 }}>
          <Crosshair size={22} color={ink} />
          <div style={{ fontWeight: 900, fontSize: 19, textTransform: sk.themed ? "uppercase" : "none", letterSpacing: sk.themed && !sk.pixel ? "0.12em" : 0, color: ink, textShadow: sk.themed && !sk.pixel ? `0 0 10px ${NEON}88` : "none" }}>{tr("Aimed shot")}</div>
        </div>
        <div style={{ fontSize: 12.5, opacity: 0.8, marginTop: 2 }}>{tr("Target: {hero}", { hero: opp.displayName || heroL(opp.hero) })}</div>
        <svg viewBox="-66 -14 332 318" style={{ display: "block", margin: "6px auto 0", overflow: "visible", width: `min(100%, ${Math.round(figH * 332 / 318)}px)`, height: "auto" }}>
          <defs>
            <linearGradient id="dxScanG" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor={ink} stopOpacity="0" /><stop offset="0.85" stopColor={ink} stopOpacity="0.22" /><stop offset="1" stopColor={ink} stopOpacity="0.55" /></linearGradient>
          </defs>
          {sk.themed && Array.from({ length: 12 }).map((_, k) => <line key={k} x1="-62" x2="262" y1={k * 27 - 10} y2={k * 27 - 10} stroke={NEON} strokeOpacity="0.06" />)}
          <ellipse cx="100" cy="287" rx="58" ry="8" fill="none" stroke={ink} strokeOpacity="0.35" strokeDasharray="3 3" />
          <g opacity={heroImpossible && !armed ? 0.4 : 1} style={{ filter: sk.themed && !sk.pixel ? `drop-shadow(0 0 2.5px ${NEON})` : "none" }}>
            <image href={sk.pixel ? BODY_WIRE_PX : BODY_WIRE} x={BODY_IMG.x} y={BODY_IMG.y} width={BODY_IMG.w} height={BODY_IMG.h} preserveAspectRatio="none"
              style={{ imageRendering: sk.pixel ? "pixelated" : "auto", filter: sk.themed ? "none" : "brightness(0)", opacity: sk.themed ? 1 : 0.6 }} />
          </g>
          {sk.themed && !sk.pixel && <rect className="dx-wire-scan" x="-62" y="-14" width="324" height="40" fill="url(#dxScanG)" pointerEvents="none" />}
          {sq("head", body.head[0], body.head[1], 16, 175, 6)}
          {sq("left", body.left[0], body.left[1], 15, -58, body.left[1] + 40)}
          {sq("right", body.right[0], body.right[1], 15, 258, body.right[1] + 40)}
        </svg>
        <div style={{ marginTop: 8, padding: "8px 10px", minHeight: "6em", boxSizing: "border-box", borderRadius: sk.pixel ? 0 : 8, background: sk.themed ? "rgba(57,255,106,0.08)" : "#f3f3f3", border: `1px solid ${sk.themed ? NEON + "55" : "#ccc"}`, fontSize: 13, lineHeight: 1.4, textAlign: "left" }}>
          <b style={{ color: AIM_PICK }}>{aimPartLabel(part)}</b>{" — "}
          {part === "head"
            ? tr("+1 extra damage (60%), +2 (30%) or +3 (10%).")
            : tr("The attack's damage also hits this hand. At 0 HP it is crippled and the item it holds is destroyed.")}
        </div>
        <div style={{ minHeight: "3.4em" }}>
        {armed ? (
          <div style={{ marginTop: 10, fontSize: 13, color: sk.themed ? "#ffe27a" : "#8a5a00", fontWeight: 700 }}>{tr("Aiming! Your next minion attack on the enemy hero is the aimed shot.")}</div>
        ) : heroImpossible ? (
          <div style={{ marginTop: 10, color: "#ff5a48", fontWeight: 800, fontSize: 14 }}>{tr("Attacking hero not possible")}<div style={{ fontWeight: 500, fontSize: 12.5, marginTop: 2 }}>{tr(heroBlock)}</div></div>
        ) : why ? (
          <div style={{ marginTop: 10, color: "#ff5a48", fontWeight: 700, fontSize: 13 }}>{tr(why)}</div>
        ) : (
          <div style={{ marginTop: 10, fontSize: 12, opacity: 0.8 }}>{tr("Costs 1 AP. Your next minion attack on the enemy hero is the aimed shot. Once per round.")}</div>
        )}
        </div>
        <div style={{ display: "flex", gap: 12, justifyContent: "center", marginTop: 14, flexWrap: "wrap" }}>
          {armed ? (
            <button type="button" {...btn(true)} onClick={() => { api.onAction({ type: "aimCancel" }); onClose(); }}>{tr("Cancel aim (+1 AP back)")}</button>
          ) : (
            <button type="button" data-tut="aim-confirm" {...btn(true)} disabled={!!why} onClick={() => { api.onAction({ type: "aim", part }); onClose(); }}>{tr("Aim · 1 AP")}</button>
          )}
          <button type="button" {...btn(false)} onClick={onClose}>{armed ? tr("Close") : tr("Cancel")}</button>
        </div>
      </div>
    </div>,
    document.body
  );
}

// Slides down for both players when a hand is crippled, showing the item that was destroyed.
const CRIPPLE_CSS = `
@keyframes dxCrippleIn { 0% { transform: translateY(-120%); opacity: 0; } 100% { transform: none; opacity: 1; } }
@keyframes dxCrippleOut { 0% { transform: none; opacity: 1; } 100% { transform: translateY(-120%); opacity: 0; } }
@keyframes dxCardBreak { 0% { transform: rotate(0) scale(1); filter: none; } 30% { transform: rotate(-4deg) scale(1.04); } 55% { transform: rotate(3deg) scale(0.98); filter: grayscale(0.6) brightness(0.8); } 100% { transform: rotate(-2deg) scale(0.96); filter: grayscale(0.85) brightness(0.62); } }
@keyframes dxStampIn { 0% { transform: rotate(-14deg) scale(2.4); opacity: 0; } 70% { transform: rotate(-14deg) scale(0.92); opacity: 1; } 100% { transform: rotate(-14deg) scale(1); opacity: 1; } }
.dx-cripple { animation: dxCrippleIn 0.45s cubic-bezier(.2,.8,.2,1) both; }
.dx-cripple.out { animation: dxCrippleOut 0.4s ease-in both; }
.dx-card-broken { animation: dxCardBreak 0.9s 0.35s ease-out both; }
.dx-stamp { animation: dxStampIn 0.45s 0.7s ease-out both; }
`;
function HandCrippleBanner({ state, myIdx }) {
  const sk = useSkin();
  const ev = state && state.handEvent;
  const seen = useRef(ev ? ev.id : null);
  const [show, setShow] = useState(null); // {ev, out}
  useEffect(() => {
    if (!ev || ev.id === seen.current) return undefined;
    seen.current = ev.id;
    setShow({ ev, out: false });
    const t1 = setTimeout(() => setShow((x) => (x && x.ev.id === ev.id ? { ...x, out: true } : x)), 10400);
    const t2 = setTimeout(() => setShow((x) => (x && x.ev.id === ev.id ? null : x)), 10850);
    return () => { clearTimeout(t1); clearTimeout(t2); };
  }, [ev ? ev.id : null]);
  if (!show) return null;
  const e = show.ev;
  const p = state.players[e.playerIdx];
  const mine = e.playerIdx === myIdx;
  const who = p.displayName || heroL(p.hero);
  const title = mine ? (e.hand === "left" ? tr("Your left hand is crippled!") : tr("Your right hand is crippled!"))
    : tr(e.hand === "left" ? "{hero}'s left hand is crippled!" : "{hero}'s right hand is crippled!", { hero: who });
  const card = e.item ? findCard(e.item) : null;
  const cc = crippledCount(p);
  const box = sk.themed
    ? { background: "linear-gradient(180deg, rgba(60,10,6,0.97), rgba(18,8,6,0.98))", color: "#f6e6dc", border: "2px solid #ff5a48", borderRadius: sk.pixel ? 0 : 14, boxShadow: "0 14px 40px rgba(0,0,0,0.7), 0 0 26px rgba(255,70,50,0.35)" }
    : { background: "#fff", color: "#111", border: "3px solid #c0392b", borderRadius: 10, boxShadow: "4px 4px 0 rgba(0,0,0,0.25)" };
  return createPortal(
    <div className={(sk.themed ? dxRootClass(sk.mode) + " " : "") + "dx-cripple" + (show.out ? " out" : "")}
      style={{ position: "fixed", top: 8, left: 8, right: 8, margin: "0 auto", maxWidth: 560, zIndex: 655, boxSizing: "border-box", fontFamily: sk.font, ...box, padding: "12px 44px 12px 14px", display: "flex", gap: 14, alignItems: "center" }}>
      <style>{CRIPPLE_CSS}</style>
      {card ? (
        <div className="dx-card-broken" style={{ position: "relative", flexShrink: 0 }}>
          {sk.themed ? <DeluxeCard card={card} scale={0.42} /> : <MiniCard cardId={card.id} small disabled />}
          <div className="dx-stamp" style={{ position: "absolute", left: "50%", top: "46%", marginLeft: "-50%", width: "100%", textAlign: "center", fontWeight: 900, fontSize: 13, letterSpacing: "0.08em", color: "#fff", background: "rgba(200,30,20,0.9)", border: "2px solid #fff", padding: "3px 0", textTransform: "uppercase" }}>{tr("Destroyed")}</div>
          <svg viewBox="0 0 100 140" preserveAspectRatio="none" style={{ position: "absolute", inset: 0, width: "100%", height: "100%", pointerEvents: "none" }}>
            <path d="M8 18 L38 52 L30 70 L58 96 L50 118 L92 134 M38 52 L72 40 L94 58 M58 96 L84 88" fill="none" stroke="rgba(15,8,6,0.85)" strokeWidth="2.4" />
          </svg>
        </div>
      ) : (
        <div style={{ flexShrink: 0, width: 54, height: 54, borderRadius: "50%", border: "2px solid #ff5a48", display: "flex", alignItems: "center", justifyContent: "center" }}><HandGlyph size={32} color={sk.themed ? "#f6e6dc" : "#111"} crippled /></div>
      )}
      <div style={{ minWidth: 0, textAlign: "left" }}>
        <div style={{ fontWeight: 900, fontSize: 16.5, color: "#ff6a55", textTransform: sk.themed ? "uppercase" : "none", letterSpacing: sk.themed && !sk.pixel ? "0.04em" : 0 }}>{title}</div>
        {card && <div style={{ fontSize: 14.5, fontWeight: 700, marginTop: 4 }}>{tr("Item destroyed: {card}", { card: cardNameL(card) })}</div>}
        <div style={{ fontSize: 12.5, marginTop: 4, opacity: 0.85 }}>{cc >= 2 ? tr("Both hands are crippled: items are played straight from the hand for +2 AP.") : tr("A crippled hand makes every item cost +1 AP.")}</div>
      </div>
      <button type="button" aria-label={tr("Close")} onClick={() => setShow(null)}
        style={{ position: "absolute", right: 8, top: 8, width: 30, height: 30, borderRadius: sk.pixel ? 0 : "50%", border: "1px solid #ff5a48", background: "rgba(0,0,0,0.25)", color: "inherit", fontSize: 18, lineHeight: "26px", padding: 0, cursor: "pointer" }}>×</button>
    </div>,
    document.body
  );
}

/* "Which hand?" when an item could go into either hand */
const HANDPICK = { ask: null, ls: new Set() };
function askEquipHand(player, onPick) { HANDPICK.ask = { player, onPick }; HANDPICK.ls.forEach((f) => f(HANDPICK.ask)); }
function HandPickHost() {
  const [ask, setAsk] = useState(HANDPICK.ask);
  useEffect(() => { const f = (a) => setAsk(a); HANDPICK.ls.add(f); return () => { HANDPICK.ls.delete(f); }; }, []);
  const sk = useSkin();
  if (!ask) return null;
  const close = () => { HANDPICK.ask = null; setAsk(null); };
  const hs = handsView(ask.player);
  const box = sk.themed
    ? { background: "linear-gradient(180deg, rgba(26,22,18,0.98), rgba(12,11,10,0.99))", color: "#efe7d8", border: `2px solid ${NEON}88`, boxShadow: `0 18px 50px rgba(0,0,0,0.7), 0 0 24px ${NEON}33`, borderRadius: sk.pixel ? 0 : 14 }
    : { background: "#fff", color: "#111", border: "3px solid #000", borderRadius: 10 };
  return createPortal(
    <div data-tut-popup="1" className={sk.themed ? dxRootClass(sk.mode) : undefined} onClick={close}
      style={{ position: "fixed", inset: 0, zIndex: 415, background: "rgba(0,0,0,0.55)", display: "flex", alignItems: "center", justifyContent: "center", padding: 12, fontFamily: sk.font }}>
      <div onClick={(e) => e.stopPropagation()} role="dialog" style={{ ...box, width: "min(380px, 100%)", padding: 18, textAlign: "center", boxSizing: "border-box" }}>
        <div style={{ fontWeight: 900, fontSize: 18, textTransform: sk.themed ? "uppercase" : "none", letterSpacing: sk.themed && !sk.pixel ? "0.08em" : 0, color: sk.themed ? NEON : "#111" }}>{tr("Equip to which hand?")}</div>
        <div style={{ display: "flex", gap: 12, marginTop: 14 }}>
          {[0, 1].map((i) => {
            const h = hs[i];
            const ok = h.hp > 0 && !h.item;
            return (
              <button key={i} type="button" disabled={!ok} onClick={() => { const f = ask.onPick; close(); f(i); }}
                style={{ flex: 1, cursor: ok ? "pointer" : "not-allowed", font: "inherit", color: "inherit", padding: "12px 8px", opacity: ok ? 1 : 0.4, borderRadius: sk.pixel ? 0 : 10,
                  background: sk.themed ? "rgba(57,255,106,0.08)" : "#f4f4f4", border: sk.themed ? `2px solid ${NEON}aa` : "2px solid #000", display: "flex", flexDirection: "column", alignItems: "center", gap: 6 }}>
                <span style={{ display: "inline-flex", transform: i === 0 ? "scaleX(-1)" : "none" }}><HandGlyph size={30} color={sk.themed ? NEON : "#111"} crippled={h.hp <= 0} /></span>
                <b style={{ fontSize: 15 }}>{i === 0 ? tr("Left hand") : tr("Right hand")}</b>
                <span style={{ display: "flex", gap: 2 }}>{Array.from({ length: HAND_HP }).map((_, k) => <i key={k} style={{ width: 9, height: 9, borderRadius: sk.pixel ? 0 : 2, background: k < h.hp ? (h.hp <= 2 ? "#ff5a48" : sk.themed ? NEON : "#1a7a3a") : (sk.themed ? "rgba(255,255,255,0.15)" : "#ccc") }} />)}</span>
                <span style={{ fontSize: 12.5, opacity: 0.85 }}>{tr("{n}/{max} HP", { n: Math.max(0, h.hp), max: HAND_HP })}</span>
              </button>
            );
          })}
        </div>
        <button type="button" onClick={close} className={sk.themed ? "dx-btn" : undefined} style={sk.themed ? { marginTop: 14, fontSize: 15 } : { marginTop: 14, fontFamily: FONT, padding: "6px 16px", border: "2px solid #000", background: "#fff", borderRadius: 4, cursor: "pointer" }}>{tr("Cancel")}</button>
      </div>
    </div>,
    document.body
  );
}
/* =========================================================================
   TUTORIAL — 6 short lessons on a prepared table, played with the real game
   rules and the real table UI. A "director" walks the player through steps:
   each step highlights where to tap (pulsing frame) and explains it. Only the
   highlighted move is allowed; the CPU's moves are scripted.
   The 600 Bullets reward is paid by the claimTutorialReward Cloud Function
   (once per account).
   ========================================================================= */
const TUT_REWARD = 600;

// a tiny shared store (the App, the table and the menus all read it)
const TUT = {
  s: { active: false, lesson: 0, step: 0, lessonDone: false, offer: false, nudge: 0, claimed: false },
  ls: new Set(),
  app: {},
  set(p) { this.s = { ...this.s, ...p }; this.ls.forEach((f) => f(this.s)); },
};
function useTut() {
  const [s, setS] = useState(TUT.s);
  useEffect(() => { const f = (x) => setS(x); TUT.ls.add(f); setS(TUT.s); return () => { TUT.ls.delete(f); }; }, []);
  return s;
}
function tutEnd() { if (TUT.s.active || TUT.s.guest) TUT.set({ active: false, lesson: 0, step: 0, lessonDone: false, guest: false }); }

/* ----- selectors of the things a step can point at (both table styles carry these) ----- */
const TS = {
  apMe: '[data-dx-hero="me"] [data-tut="ap"]',
  card: (n) => `[data-tut-card="${n}"]`,
  confirm: '[data-tut="confirm-play"]',
  mine: (n) => `[data-tut-side="me"][data-tut-minion="${n}"]`,
  theirs: (n) => `[data-tut-side="opp"][data-tut-minion="${n}"]`,
  theirAll: '[data-tut-side="opp"][data-tut-minion]',
  oppHero: '[data-dx-hero="opp"]',
  power: '[data-tut="power"]',
  endTurn: '[data-tut="endturn"]',
  handsMe: '[data-dx-hero="me"] .dx-hands-badge',
  handsOpp: '[data-dx-hero="opp"] .dx-hands-badge',
  useSlot: '[data-tut="use-slot"]',
  aimBtn: '.dx-aim-btn',
  aimPart: (p) => `[data-tut="aim-${p}"]`,
  aimGo: '[data-tut="aim-confirm"]',
  mullGo: '[data-tut="mull-go"]',
  perkOpt: '.dx-perk-opt',
};

/* ----- helpers for the lesson scripts ----- */
const tMe = (st) => st.players[0], tOpp = (st) => st.players[1];
const tOnBoard = (pl, name) => pl.board.filter((m) => m.name === name).length;
const tHandName = (st, a) => { const id = tMe(st).hand[a.handIdx]; const c = id && findCard(id); return c ? c.name : null; };
const tSlotName = (st, a) => { const h = handsView(tMe(st))[a.slot]; const c = h && h.item && findCard(h.item); return c ? c.name : null; };
const tMinion = (st, idx, uid) => st.players[idx].board.find((m) => m.uid === uid);
const allowPlay = (name) => (a, st) => a.type === "playCard" && a.slot === undefined && tHandName(st, a) === name;
const allowEquip = (name) => (a, st) => a.type === "equip" && tHandName(st, a) === name;
const allowSlotUse = (name) => (a, st) => a.type === "playCard" && (a.slot === 0 || a.slot === 1) && tSlotName(st, a) === name;
const allowAttack = (from, to) => (a, st) => {
  if (a.type !== "attack") return false;
  const m = tMinion(st, 0, a.attackerUid);
  if (!m || m.name !== from) return false;
  if (to === "hero") return a.target.type === "hero";
  const d = a.target.type === "minion" && tMinion(st, 1, a.target.uid);
  return !!d && d.name === to;
};

