/* sparks + swoosh (rare and better) and fireworks (unique) when a card turns */
const FX_COLORS = { rare: ["#7cc8ff", "#3f9dff"], epic: ["#8fd0ff", "#c48bff"], unique: ["#9ad8ff", "#ffd25a"] };
const FW_COLORS = ["#ff5a5a", "#ffd25a", "#7cff8a", "#7cc8ff", "#d68bff", "#ff9a3a"];
function RevealFx({ rarity, w, h }) {
  const [c1, c2] = FX_COLORS[rarity] || FX_COLORS.rare;
  const n = rarity === "rare" ? 16 : 24;
  const rx = w * 0.62, ry = h * 0.58;
  const sparks = Array.from({ length: n }, (_, i) => {
    const a = (360 / n) * i + (i % 3) * 5;
    const rad = (a * Math.PI) / 180;
    const r0 = Math.hypot(Math.sin(rad) * w * 0.48, Math.cos(rad) * h * 0.48);
    return { a, r0, r1: r0 + 40 + (i % 4) * 16, c: i % 2 ? c1 : c2, d: (i % 5) * 0.03 };
  });
  const bursts = rarity === "unique" ? [[-0.75, -0.55, 0.15], [0.8, -0.45, 0.45], [-0.85, 0.35, 0.75], [0.75, 0.5, 1.0], [0, -0.85, 1.3], [-0.2, 0.9, 1.55], [0.55, -0.9, 1.85]] : [];
  return (
    <div className="dx-fx">
      <div className="fl" style={{ left: -w * 0.6, top: -h * 0.6, width: w * 1.2, height: h * 1.2, background: `radial-gradient(ellipse, rgba(255,255,255,0.9), ${c1}88 35%, rgba(0,0,0,0) 70%)` }} />
      <svg style={{ left: -rx, top: -ry, width: rx * 2, height: ry * 2 }} viewBox={`${-rx} ${-ry} ${rx * 2} ${ry * 2}`}>
        <ellipse className="sw" cx="0" cy="0" rx={rx} ry={ry} pathLength="100" stroke={c1} strokeWidth="7" style={{ filter: `drop-shadow(0 0 6px ${c1}) drop-shadow(0 0 14px ${c1})` }} />
        <ellipse className="sw" cx="0" cy="0" rx={rx * 0.92} ry={ry * 0.92} pathLength="100" stroke="#ffffff" strokeWidth="3" transform="rotate(180)" style={{ animationDelay: "0.08s", filter: `drop-shadow(0 0 8px ${c2})` }} />
      </svg>
      {sparks.map((p, i) => <i key={i} className="sp" style={{ "--a": p.a + "deg", "--r0": p.r0 + "px", "--r1": p.r1 + "px", "--c": p.c, animationDelay: p.d + "s" }} />)}
      {bursts.map(([bx, by, d], j) => (
        <div key={"b" + j} className="dx-fw" style={{ left: bx * w, top: by * h, animationDelay: d + "s" }}>
          <i className="c" style={{ "--c": FW_COLORS[j % FW_COLORS.length], animationDelay: d + "s" }} />
          {Array.from({ length: 24 }, (_, k) => <i key={k} className="p" style={{ "--a": k * 15 + "deg", "--d": 70 + (k % 3) * 22 + "px", "--c": FW_COLORS[(j + (k % 2) * 2) % FW_COLORS.length], animationDelay: d + "s" }} />)}
        </div>
      ))}
    </div>
  );
}

/* the pack cracks, then breaks into shards flying out from its middle */
const SHARD_RIM = [[0, 0], [30, 0], [62, 0], [100, 0], [100, 28], [100, 60], [100, 100], [70, 100], [38, 100], [0, 100], [0, 66], [0, 34]];
const SHARD_C = [52, 47];
function PackShatter({ scale }) {
  return (
    <div style={{ position: "relative", width: 200 * scale, height: 290 * scale }}>
      {SHARD_RIM.map((p, i) => {
        const q = SHARD_RIM[(i + 1) % SHARD_RIM.length];
        const cx = (p[0] + q[0] + SHARD_C[0]) / 3 - SHARD_C[0], cy = (p[1] + q[1] + SHARD_C[1]) / 3 - SHARD_C[1];
        const len = Math.hypot(cx, cy) || 1;
        const dist = 380 + (i % 3) * 120;
        return (
          <div key={i} className="dx-shard" style={{ clipPath: `polygon(${SHARD_C[0]}% ${SHARD_C[1]}%, ${p[0]}% ${p[1]}%, ${q[0]}% ${q[1]}%)`, "--tx": (cx / len) * dist + "px", "--ty": (cy / len) * dist + "px", "--r": (i % 2 ? 1 : -1) * (120 + i * 25) + "deg" }}>
            <DiamondPackArt scale={scale} />
          </div>
        );
      })}
    </div>
  );
}
function PackCracks() {
  return (
    <svg className="dx-crack" viewBox="0 0 200 290" style={{ position: "absolute", inset: 0, width: "100%", height: "100%", pointerEvents: "none", overflow: "visible", filter: "drop-shadow(0 0 6px #ffb84a)" }}>
      {["M104 136 L80 98 L86 70 L60 30", "M104 136 L140 110 L150 80 L178 60", "M104 136 L128 170 L120 210 L150 262", "M104 136 L70 160 L52 200 L22 214", "M104 136 L98 90 L112 52", "M104 136 L150 150 L188 170"].map((d, i) => (
        <g key={i}>
          <path d={d} pathLength="100" fill="none" stroke="#120d06" strokeWidth={i < 4 ? 6 : 4} strokeLinejoin="round" style={{ animationDelay: i * 0.05 + "s" }} />
          <path d={d} pathLength="100" fill="none" stroke="#fff6c8" strokeWidth={i < 4 ? 2.2 : 1.6} strokeLinejoin="round" style={{ animationDelay: i * 0.05 + "s" }} />
        </g>
      ))}
    </svg>
  );
}
function PackBlast() {
  return (
    <div className="dx-blast">
      <img className="img" src={EXPLOSION_SRC} alt="" draggable={false} />
      <img className="img2" src={EXPLOSION_SRC} alt="" draggable={false} />
      <i className="core" />
      <i className="wave" />
      <i className="wave w2" />
      {Array.from({ length: 36 }, (_, i) => <i key={"e" + i} className="em" style={{ "--a": i * 10 + (i % 4) * 3 + "deg", "--d": 260 + ((i * 37) % 5) * 80 + "px", animationDelay: (i % 6) * 0.025 + "s", height: 16 + (i % 3) * 12 }} />)}
      {Array.from({ length: 16 }, (_, i) => <i key={"r" + i} className="rock" style={{ "--a": i * 22.5 + 9 + "deg", "--d": 300 + (i % 4) * 110 + "px", "--s": (i % 2 ? 1 : -1) * 540 + "deg", animationDelay: (i % 4) * 0.04 + "s", transform: `scale(${0.6 + (i % 3) * 0.45})` }} />)}
    </div>
  );
}

/* "you have unopened packs" count badge (like an unread-messages dot) */
const PKB_CSS = `
.dx-pkb { position: absolute; top: -7px; right: -13px; z-index: 30; pointer-events: none; min-width: 16px; height: 16px; padding: 0 4px; box-sizing: border-box; border-radius: 999px;
  display: inline-flex; align-items: center; justify-content: center; font: 800 10px/1 system-ui, -apple-system, "Segoe UI", sans-serif; letter-spacing: 0; text-transform: none; color: #fff; background: #ff7a00; box-shadow: 0 0 0 2px rgba(0,0,0,0.55); }
.dx-pkb.np { box-shadow: 0 0 0 2px #fff; }
.dx-pk-dot { position: static; margin-left: 8px; vertical-align: middle; }
`;
function PacksBubble({ n, inline }) {
  const sk = useSkinS();
  if (!n || n <= 0) return null;
  return (
    <>
      <style>{PKB_CSS}</style>
      <span className={"dx-pkb" + (sk.themed ? "" : " np") + (inline ? " dx-pk-dot" : "")} aria-label={n === 1 ? tr("1 pack to open!") : tr("{n} packs to open!", { n })}>{n > 99 ? "99+" : n}</span>
    </>
  );
}

/* Normal / Diamond switch for the deck builders (only one version is drawn at a time - lighter on phones) */
function DeckViewToggle({ view, setView, profile }) {
  const sk = useSkinS();
  const has = profile && profile.diamonds && Object.values(profile.diamonds).some((n) => n > 0);
  const opts = [["normal", tr("Normal")], ["diamond", "◆ " + tr("Diamond")]];
  return (
    <div style={{ display: "inline-flex", marginTop: 10, marginBottom: 6, border: sk.themed ? "1px solid rgba(255,255,255,0.3)" : "2px solid #000", borderRadius: sk.pixel ? 0 : sk.themed ? 999 : 6, overflow: "hidden" }}>
      {opts.map(([v, l]) => (
        <button key={v} type="button" onClick={() => setView(v)} disabled={v === "diamond" && !has}
          style={{ border: "none", padding: sk.themed ? "7px 18px" : "5px 14px", cursor: v === "diamond" && !has ? "default" : "pointer", font: "inherit", fontSize: 13, fontWeight: 800, letterSpacing: "0.05em", opacity: v === "diamond" && !has ? 0.45 : 1,
            background: view === v ? (sk.themed ? (v === "diamond" ? "linear-gradient(180deg,#ffffff,#bfe3ff)" : "#e0a94a") : "#000") : "transparent", color: view === v ? (sk.themed ? "#14100a" : "#fff") : "inherit" }}>{l}</button>
      ))}
    </div>
  );
}

/* a Diamond minion on the table: the frame and its crown are one crystal shape (no outline); the stat bar sits inside the crown */
const MIN_CROWN_TOP = 30;
const MIN_CROWN_PTS = [[0, -4], [24, -20], [42, -9], [75, -30], [108, -9], [126, -20], [150, -4]];
function minDiaOutline(taunt, pixel) {
  const W = DX_MIN_W, H = DX_MIN_H, r = taunt ? 34 : 13, steps = pixel ? 3 : 8, pts = MIN_CROWN_PTS.slice();
  for (let k = 0; k <= steps; k++) { const a = (k / steps) * Math.PI / 2; pts.push([W - r + r * Math.cos(a), H - r + r * Math.sin(a)]); }
  for (let k = 0; k <= steps; k++) { const a = (k / steps) * Math.PI / 2; pts.push([r - r * Math.sin(a), H - r + r * Math.cos(a)]); }
  return pts.map(([x, y]) => (pixel ? [Math.round(x / 3) * 3, Math.round(y / 3) * 3] : [+x.toFixed(1), +y.toFixed(1)]));
}
function DiamondMinionCrown({ rarity, pixel, taunt }) {
  const t = DIA_TINT[rarity] || DIA_TINT.common;
  const pts = minDiaOutline(taunt, pixel);
  const clip = "polygon(" + pts.map(([x, y]) => `${x}px ${y + MIN_CROWN_TOP}px`).join(",") + ")";
  const outline = pts.map((p) => p.join(",")).join(" ");
  return (
    <>
      <div className="dx-mc-shape" style={{ ...diaStyle(rarity).vars, top: -MIN_CROWN_TOP, height: DX_MIN_H + MIN_CROWN_TOP, filter: pixel ? undefined : `drop-shadow(0 0 7px rgba(${t.rgb},0.85)) drop-shadow(0 8px 10px rgba(0,0,0,0.6))` }}>
        <i className="dx-mc-body" style={{ clipPath: clip, WebkitClipPath: clip }} />
        {!pixel && <i className="dx-mc-shade" style={{ clipPath: clip, WebkitClipPath: clip }} />}
      </div>
      {!pixel && <div className="dx-mc-star" style={diaStyle(rarity).vars} />}
      {/* ready / target / selected glow in the minion's own crystal shape */}
      <svg className="dx-mc-glow" viewBox={`0 ${-MIN_CROWN_TOP - 2} 150 ${DX_MIN_H + MIN_CROWN_TOP + 4}`} width="150" height={DX_MIN_H + MIN_CROWN_TOP + 4} style={{ position: "absolute", left: 0, top: -MIN_CROWN_TOP - 2, overflow: "visible", pointerEvents: "none", zIndex: 3 }} shapeRendering={pixel ? "crispEdges" : undefined}>
        <polygon points={outline} fill="none" strokeWidth={pixel ? 6 : 4} strokeLinejoin={pixel ? "miter" : "round"} />
      </svg>
    </>
  );
}

/* "Are you sure?" before anything is bought: askConfirm(text) -> Promise<boolean> */
function askConfirm(text, opts) {
  return new Promise((resolve) => shopSet({ ask: { text, resolve, ok: opts && opts.ok, danger: opts && opts.danger } }));
}
function ConfirmHost() {
  const [ask, setAsk] = useState(SHOP.ask || null);
  useEffect(() => { const f = (x) => setAsk(x.ask || null); SHOP.ls.add(f); return () => { SHOP.ls.delete(f); }; }, []);
  const sk = useSkinS();
  if (!ask) return null;
  const done = (v) => { shopSet({ ask: null }); ask.resolve(v); };
  const panel = sk.themed
    ? { background: "linear-gradient(180deg, rgba(34,29,24,0.98), rgba(14,12,10,0.99))", color: "#efe7d8", border: "1px solid rgba(255,200,110,0.45)", borderRadius: sk.pixel ? 0 : 14, boxShadow: "0 20px 50px rgba(0,0,0,0.6)" }
    : { background: "#fff", color: "#111", border: "3px solid #000", borderRadius: 10 };
  return createPortal(
    <div data-tut-popup="1" className={sk.themed ? dxRootClass(sk.mode) : undefined} onClick={() => done(false)}
      style={{ position: "fixed", inset: 0, zIndex: 700, background: "rgba(0,0,0,0.6)", display: "flex", alignItems: "center", justifyContent: "center", padding: 16, fontFamily: sk.font }}>
      <div onClick={(e) => e.stopPropagation()} role="dialog" aria-modal="true" style={{ ...panel, width: "min(380px, 100%)", padding: 20, textAlign: "center", boxSizing: "border-box" }}>
        <div style={{ fontSize: 16, fontWeight: 800, lineHeight: 1.4 }}>{ask.text}</div>
        <div style={{ display: "flex", gap: 10, marginTop: 18, justifyContent: "center", flexWrap: "wrap" }}>
          <button type="button" autoFocus className={sk.themed ? "fx-btn fx-btn-primary" : undefined} style={sk.themed ? { minWidth: 120, ...(ask.danger ? { background: "linear-gradient(180deg,#d9534a,#9e2a22)", borderColor: "#ff8d80", color: "#fff" } : {}) } : npBtn(true, { minWidth: 110, ...(ask.danger ? { background: "#c0392b", border: "2px solid #c0392b" } : {}) })} onClick={() => done(true)}>{ask.ok || tr("Buy")}</button>
          <button type="button" className={sk.themed ? "fx-btn" : undefined} style={sk.themed ? { minWidth: 120 } : npBtn(false, { minWidth: 110 })} onClick={() => done(false)}>{tr("Cancel")}</button>
        </div>
      </div>
    </div>,
    document.body
  );
}

/* ◆ switch next to a card in the deck list: play this card in its Diamond version (needs a Diamond copy for every copy in the deck) */
function DeckDiaToggle({ card, n, dia, setDia, profile, themed }) {
  const own = myDiamondCount(profile, card.id);
  if (own <= 0) return null;
  const enough = own >= n;
  const on = dia.includes(card.id) && enough;
  const title = !enough ? tr("You need {n} Diamond copies for this", { n }) : on ? tr("Using the Diamond version — tap to use the normal one") : tr("Use the Diamond version");
  return (
    <button type="button" title={title} aria-pressed={on} disabled={!enough}
      onClick={(e) => { e.stopPropagation(); setDia(on ? dia.filter((x) => x !== card.id) : [...dia, card.id]); }}
      style={{ flexShrink: 0, width: 24, height: 22, padding: 0, cursor: enough ? "pointer" : "not-allowed", fontSize: 12, lineHeight: "20px", borderRadius: themed ? 6 : 4,
        border: themed ? `1px solid ${on ? "#e6f4ff" : "rgba(255,255,255,0.25)"}` : "1px solid #000",
        background: on ? (themed ? "linear-gradient(180deg,#ffffff,#9fd4ff)" : "#1a5aa0") : "transparent",
        color: on ? (themed ? "#0b2a52" : "#fff") : (themed ? "rgba(255,255,255,0.55)" : "#1a5aa0"), opacity: enough ? 1 : 0.35,
        boxShadow: on && themed ? "0 0 8px rgba(160,210,255,0.8)" : "none" }}>◆</button>
  );
}

/* small "(i) Info" button: the help text lives in a pop-up instead of taking screen space */
function InfoButton({ title, children, style }) {
  const sk = useSkinS();
  const [open, setOpen] = useState(false);
  const panel = sk.themed
    ? { background: "linear-gradient(180deg, rgba(34,29,24,0.98), rgba(14,12,10,0.99))", color: "#efe7d8", border: "1px solid rgba(255,200,110,0.45)", borderRadius: sk.pixel ? 0 : 14, boxShadow: "0 20px 50px rgba(0,0,0,0.6)" }
    : { background: "#fff", color: "#111", border: "3px solid #000", borderRadius: 10 };
  return (
    <>
      <button type="button" onClick={(e) => { e.stopPropagation(); setOpen(true); }} aria-label={tr("Info")}
        style={{ display: "inline-flex", alignItems: "center", gap: 6, padding: "4px 10px 4px 5px", cursor: "pointer", font: "inherit", fontSize: 12.5, fontWeight: 800, letterSpacing: "0.04em", verticalAlign: "middle",
          borderRadius: sk.pixel ? 0 : 999, border: sk.themed ? "1px solid rgba(255,255,255,0.28)" : "2px solid #000", background: sk.themed ? "rgba(0,0,0,0.35)" : "#fff", color: sk.themed ? "#efe7d8" : "#111", ...style }}>
        <span style={{ width: 18, height: 18, borderRadius: sk.pixel ? 0 : "50%", display: "inline-flex", alignItems: "center", justifyContent: "center", fontFamily: "Georgia, serif", fontStyle: "italic", fontWeight: 900, fontSize: 12,
          background: sk.themed ? "var(--fx-gold, #e0a94a)" : "#000", color: sk.themed ? "#14100a" : "#fff" }}>i</span>
        {tr("Info")}
      </button>
      {open && createPortal(
        <div data-tut-popup="1" className={sk.themed ? dxRootClass(sk.mode) : undefined} onClick={() => setOpen(false)}
          style={{ position: "fixed", inset: 0, zIndex: 720, background: "rgba(0,0,0,0.6)", display: "flex", alignItems: "center", justifyContent: "center", padding: 16, fontFamily: sk.font }}>
          <div onClick={(e) => e.stopPropagation()} role="dialog" aria-modal="true" style={{ ...panel, width: "min(440px, 100%)", maxHeight: "86vh", overflowY: "auto", padding: 20, boxSizing: "border-box", textAlign: "left" }}>
            <div style={{ fontWeight: 900, fontSize: 17, marginBottom: 10, textTransform: sk.themed ? "uppercase" : "none", letterSpacing: sk.themed && !sk.pixel ? "0.06em" : 0, color: sk.themed ? "var(--fx-gold, #e0a94a)" : "#111" }}>{title}</div>
            <div style={{ fontSize: 14, lineHeight: 1.5, display: "flex", flexDirection: "column", gap: 8 }}>{children}</div>
            <div style={{ textAlign: "center", marginTop: 16 }}>
              <button type="button" className={sk.themed ? "fx-btn" : undefined} style={sk.themed ? { minWidth: 120 } : npBtn(false, { minWidth: 110 })} onClick={() => setOpen(false)}>{tr("Close")}</button>
            </div>
          </div>
        </div>, document.body)}
    </>
  );
}

/* Notepad styles: a small hamburger menu in the top-right corner */
function NpMenu({ go, packs }) {
  const [open, setOpen] = useState(false);
  const [rules, setRules] = useState(false);
  const ref = useRef(null);
  useEffect(() => {
    if (!open) return undefined;
    const away = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener("pointerdown", away, true);
    return () => document.removeEventListener("pointerdown", away, true);
  }, [open]);
  const pick = (fn) => { setOpen(false); fn(); };
  const items = [
    ["leaderboard", tr("Leaderboard"), () => go("leaderboard")],
    ["quests", tr("Quests"), () => go("quests")],
    ["collection", tr("Collection"), () => go("collection")],
    ["packs", tr("Packs"), () => go("packs")],
    ["rules", tr("Rules"), () => setRules(true)],
    ["tutorial", tr("Tutorial"), () => TUT.app.start && TUT.app.start(0)],
    ["settings", tr("Settings"), () => go("settings")],
  ];
  const row = { display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8, width: "100%", padding: "8px 12px", fontFamily: FONT, fontSize: 12.5, fontWeight: 700, textAlign: "left", cursor: "pointer", border: "none", borderTop: "1px solid #ddd", background: "#fff", color: "#111" };
  return (
    <div ref={ref} style={{ position: "relative", display: "inline-block", marginTop: 4 }}>
      <button type="button" aria-label={tr("Open menu")} aria-expanded={open} onClick={() => setOpen((o) => !o)}
        style={{ position: "relative", display: "inline-flex", alignItems: "center", gap: 6, padding: "3px 9px", fontFamily: FONT, fontSize: 11, fontWeight: 700, border: "2px solid #000", background: open ? "#000" : "#fff", color: open ? "#fff" : "#000", borderRadius: 4, cursor: "pointer" }}>
        <span aria-hidden="true" style={{ display: "inline-flex", flexDirection: "column", gap: 2 }}>{[0, 1, 2].map((i) => <i key={i} style={{ display: "block", width: 13, height: 2, background: "currentColor" }} />)}</span>
        {tr("Menu")}
        {packs > 0 && <PacksBubble n={packs} />}
      </button>
      {open && (
        <div role="menu" style={{ position: "absolute", right: 0, top: "calc(100% + 6px)", zIndex: 300, width: 190, border: "2px solid #000", borderRadius: 6, background: "#fff", boxShadow: "4px 4px 0 rgba(0,0,0,0.2)", overflow: "hidden" }}>
          <button type="button" role="menuitem" onClick={() => pick(() => go("shop"))}
            style={{ ...row, borderTop: "none", background: "#1e78e0", color: "#fff", borderBottom: "2px solid #0a4fa0" }}>{tr("Shop")}</button>
          {items.map(([id, label, fn]) => (
            <button key={id} type="button" role="menuitem" onClick={() => pick(fn)} style={row}>
              <span>{label}</span>
              {id === "packs" && <PacksBubble n={packs} inline />}
            </button>
          ))}
        </div>
      )}
      {rules && <RulesModal onClose={() => setRules(false)} />}
    </div>
  );
}

/* =========================================================================
   WIN REWARDS. The first 5 wins (CPU wins count too) unlock the reward items:
   win 1 VHS Tape Recording, win 2 Egg Shaped Package, win 3 Big Birthday Cake,
   win 4 the six hero items, win 5 two Diamond Packs. The server keeps the count
   (profile.starterWins) and the unlocked cards (profile.rewardCardIds); this
   shows the red "locked" banner and the congratulations pop-up.
   ========================================================================= */
const STARTER_WIN_STEPS = 5;
const RW_CSS = `
.rw-lock { position: absolute; left: -3px; right: -3px; top: 10%; z-index: 14; pointer-events: none; padding: 3px 4px; text-align: center;
  font: 900 9.5px/1.15 system-ui, -apple-system, "Segoe UI", sans-serif; letter-spacing: 0.02em; text-transform: uppercase; color: #fff;
  background: linear-gradient(180deg, #e8402f, #a3170c); border-top: 1px solid #ff9a8a; border-bottom: 1px solid #5e0a03;
  box-shadow: 0 2px 6px rgba(0,0,0,0.55), 0 0 10px rgba(255,60,40,0.45); text-shadow: 0 1px 0 rgba(0,0,0,0.5); }
.rw-lock.big { position: static; display: inline-block; margin-top: 4px; padding: 6px 12px; font-size: 12.5px; border-radius: 4px; }
.dx-coll-tile.locked.rw, .fx-pcard.is-locked.rw { opacity: 1 !important; filter: none !important; }
.dx-coll-tile.locked.rw > :first-child, .fx-pcard.is-locked.rw > :first-child { opacity: 0.45; filter: grayscale(0.8); }
@keyframes rwFloat { 0%,100% { transform: translateY(0) rotate(-1.5deg); } 50% { transform: translateY(-14px) rotate(1.5deg); } }
@keyframes rwIn { 0% { opacity: 0; transform: scale(0.6) translateY(40px); } 100% { opacity: 1; transform: none; } }
@keyframes rwTitle { 0% { opacity: 0; transform: scale(2.2); letter-spacing: 0.4em; } 60% { opacity: 1; } 100% { opacity: 1; transform: none; } }
.rw-back { position: fixed; inset: 0; z-index: 470; display: flex; align-items: center; justify-content: center; padding: 14px; box-sizing: border-box; overflow: hidden;
  background: radial-gradient(ellipse at 50% 40%, rgba(60,40,10,0.92), rgba(5,4,3,0.96) 70%); }
.rw-back.np { background: rgba(0,0,0,0.75); }
.rw-box { position: relative; z-index: 2; width: min(920px, 100%); max-height: 100%; overflow-y: auto; text-align: center; color: #f3ecdf; }
.rw-back.np .rw-box { background: #fff; color: #111; border: 3px solid #000; border-radius: 10px; padding: 16px; width: min(620px, 100%); }
.rw-title { font-weight: 900; font-size: clamp(26px, 6vw, 46px); letter-spacing: 0.08em; text-transform: uppercase; animation: rwTitle 0.8s cubic-bezier(.2,.8,.2,1) both;
  background: linear-gradient(90deg, #ffd25a, #fff6c8, #ffb03a, #fff6c8, #ffd25a); background-size: 200% 100%; -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 0 14px rgba(255,190,60,0.6)); }
.rw-back.np .rw-title { background: none; color: #111; filter: none; -webkit-background-clip: border-box; background-clip: border-box; }
.rw-cards { display: flex; flex-wrap: wrap; justify-content: center; align-items: flex-end; margin: 28px 0 10px; }
.rw-card { animation: rwIn 0.6s cubic-bezier(.2,.8,.2,1) both; }
.rw-card > div { animation: rwFloat 3.2s ease-in-out infinite; }
.rw-card.dim { opacity: 0.55; filter: grayscale(0.6); }
.rw-fw-layer { position: absolute; inset: 0; pointer-events: none; z-index: 1; }
.rw-fw-layer .dx-fw { position: absolute; }
`;
if (typeof document !== "undefined" && !document.getElementById("rw-css")) {
  const st = document.createElement("style");
  st.id = "rw-css";
  st.textContent = RW_CSS;
  document.head.appendChild(st);
}

function RewardLockBanner({ big }) {
  return <div className={"rw-lock" + (big ? " big" : "")}><div style={{ fontSize: big ? 14 : 11 }}>{tr("Locked")}</div><div style={{ fontWeight: 700, opacity: 0.95 }}>{tr("Win games to unlock")}</div></div>;
}

// Fireworks going off all over the screen, again and again.
function RewardFireworks() {
  const [tick, setTick] = useState(0);
  useEffect(() => { const t = setInterval(() => setTick((n) => n + 1), 1900); return () => clearInterval(t); }, []);
  const bursts = Array.from({ length: 4 }, (_, j) => ({ x: 8 + Math.random() * 84, y: 8 + Math.random() * 55, d: j * 0.35, j: (j + tick) % FW_COLORS.length }));
  return (
    <div className="rw-fw-layer" key={tick}>
      {bursts.map((b, j) => (
        <div key={j} className="dx-fw" style={{ left: b.x + "%", top: b.y + "%", animationDelay: b.d + "s" }}>
          <i className="c" style={{ "--c": FW_COLORS[b.j], animationDelay: b.d + "s" }} />
          {Array.from({ length: 24 }, (_, k) => <i key={k} className="p" style={{ "--a": k * 15 + "deg", "--d": 80 + (k % 3) * 26 + "px", "--c": FW_COLORS[(b.j + (k % 2) * 2) % FW_COLORS.length], animationDelay: b.d + "s" }} />)}
        </div>
      ))}
    </div>
  );
}

// Shown on the main page after a win that earned one of the 5 starter rewards.
function StarterRewardHost({ profile, uid, active, onShop, onPacks }) {
  const key = uid ? "ab_rw_seen_" + uid : null;
  const wins = Math.min(STARTER_WIN_STEPS, (profile && profile.starterWins) || 0);
  const [seen, setSeen] = useState(null);
  useEffect(() => {
    if (!key || !profile) return;
    let v = null;
    try { v = localStorage.getItem(key); } catch (e) { v = null; }
    if (v === null) { v = String(wins); try { localStorage.setItem(key, v); } catch (e) { /* private mode */ } }
    setSeen(Number(v) || 0);
  }, [key, !!profile]);
  if (!active || seen === null || wins <= seen) return null;
  const step = seen + 1;
  const close = () => { try { localStorage.setItem(key, String(step)); } catch (e) { /* ignore */ } setSeen(step); };
  return <StarterRewardPopup step={step} profile={profile} onClose={close} onShop={() => { close(); onShop && onShop(); }} onPacks={() => { close(); onPacks && onPacks(); }} />;
}

function StarterRewardPopup({ step, profile, onClose, onShop, onPacks }) {
  const sk = useSkinS();
  const cards = CARD_DB.filter((c) => c.reward === step);
  const vw = window.innerWidth, vh = window.innerHeight;
  const many = cards.length > 1;
  const cols = many ? (vw < 700 ? 3 : 6) : 1, rows = many ? Math.ceil(cards.length / cols) : 1;
  const boxW = Math.min(920, vw - 28);
  const sc = Math.max(0.28, Math.min(many ? 0.8 : 1.0, (boxW / cols - 14) / DX_CARD_W, ((vh - (many ? 300 : 340)) / rows - (many ? 26 : 30)) / DX_CARD_H));
  const heroesOwned = profile && profile.unlockedAll ? HEROES.length : HEROES.filter((h) => isHeroUnlocked(h, profile)).length;
  const btn = (primary) => (sk.themed ? { className: "fx-btn" + (primary ? " fx-btn-primary" : ""), style: { fontSize: 16, minWidth: 150 } } : { style: npBtn(primary, { fontSize: 14, minWidth: 130 }) });
  const head = step === 5 ? tr("2 free Diamond Packs!") : step === 1 ? tr("First win! {card} + a free Diamond Pack!", { card: cardNameL(cards[0]) }) : many ? tr("6 hero items unlocked!") : tr("{card} unlocked!", { card: cardNameL(cards[0]) });
  return createPortal(
    <div data-kwtap="1" className={"rw-back" + (sk.themed ? " " + dxRootClass(sk.mode) : " np")} style={{ fontFamily: sk.font }} onClick={(e) => e.stopPropagation()}>
      <style>{SHOP_CSS}</style>
      {sk.themed && <RewardFireworks />}
      <div className="rw-box">
        <div className="rw-title">{tr("Congratulations!")}</div>
        <div style={{ fontWeight: 900, fontSize: 19, marginTop: 8, color: sk.themed ? "#ffd77a" : undefined }}>{head}</div>
        <div className="rw-cards" style={{ gap: many ? 10 : 0 }}>
          {step === 5
            ? [0, 1].map((i) => <div key={i} className="rw-card" style={{ animationDelay: i * 0.15 + "s", margin: "0 8px" }}><div style={{ animationDelay: i * 0.7 + "s" }}><DiamondPackArt scale={Math.min(1, (vh - 360) / 290, (vw - 60) / 2 / 210)} /></div></div>)
            : cards.map((c, i) => {
              const playable = !c.hero || isHeroUnlocked(c.hero, profile);
              return (
                <div key={c.id} className={"rw-card" + (many && !playable ? " dim" : "")} style={{ animationDelay: i * 0.12 + "s" }}>
                  <div style={{ animationDelay: (i % 3) * 0.5 + "s" }}>
                    {sk.themed ? <DeluxeCard card={c} scale={sc} /> : <div style={{ transform: `scale(${many ? 1 : 1.4})`, margin: many ? 4 : "36px 30px" }}><MiniCard cardId={c.id} /></div>}
                    {many && <div style={{ fontSize: 11, fontWeight: 800, marginTop: 4, opacity: 0.85 }}>{heroL(c.hero)}{playable ? " ✓" : ""}</div>}
                  </div>
                </div>
              );
            }).concat(step === 1 ? [<div key="pack" className="rw-card" style={{ animationDelay: "0.25s", margin: "0 12px", alignSelf: "center" }}><div style={{ animationDelay: "0.6s" }}><DiamondPackArt scale={Math.min(0.9, (vh - 380) / 290, (vw - 60) / 2 / 210)} /></div></div>] : [])}
        </div>
        <div style={{ fontSize: 14, lineHeight: 1.5, maxWidth: 560, margin: "0 auto" }}>
          {step === 1 && <div>{tr("The item is in your collection now. Open your Diamond Pack to get 6 shiny cards!")}</div>}
          {step > 1 && step <= 3 && <div>{tr("It's in your collection now. Add it to any deck in the Deck Builder.")}</div>}
          {step === 4 && <>
            <div>{tr("You own {n} of 6 heroes, so you can play {n} of these cards now.", { n: heroesOwned, count: heroesOwned })}</div>
            {heroesOwned < HEROES.length && <div style={{ marginTop: 4 }}>{tr("Unlock the other heroes in the Shop to play the rest.")}</div>}
          </>}
          {step === 5 && <div>{tr("Open them in Packs. Good luck out there!")}</div>}
        </div>
        <div style={{ display: "flex", gap: 10, justifyContent: "center", flexWrap: "wrap", marginTop: 16 }}>
          {step === 4 && heroesOwned < HEROES.length && <button type="button" {...btn(false)} onClick={onShop}>{tr("Shop")}</button>}
          {step === 5 && <button type="button" {...btn(false)} onClick={onPacks}>{tr("Open Packs")}</button>}
          {step === 1 ? <>
            <button type="button" {...btn(true)} onClick={onPacks}>{tr("Open your pack!")}</button>
            <button type="button" {...btn(false)} onClick={onClose}>{tr("Later")}</button>
          </> : <button type="button" {...btn(true)} onClick={onClose}>{tr("Awesome!")}</button>}
        </div>
      </div>
    </div>,
    document.body
  );
}

/* =========================================================================
   SURPRISE BADGE — a "?" in the hero's colour while that hero has a Surprise
   (perk or item) waiting. The owner sees the full list; the opponent only
   sees how many are hidden and whether each came from a perk (with its level
   colour) or from a card (white on black).
   ========================================================================= */
function activeSurprises(player) {
  return (player && player.perks || []).filter((x) => !x.depleted && PERK_BY_ID[x.id] && PERK_BY_ID[x.id].surprise);
}
function SurpriseBadge({ player, owner, size = 26, style }) {
  const list = activeSurprises(player);
  const [tip, setTip] = useState(null); // { rect, pinned }
  const ref = useRef(null);
  const lastRect = useRef(null);
  const [poof, setPoof] = useState(null); // { key, rect } while the "SURPRISE!" reveal plays
  const [sel, setSel] = useState(null); // { i, rect }: the Surprise whose effect is shown in a small pop-up
  const mode = useDisplay().mode;
  const themed = isThemedMode(mode), pixel = mode === "pixel";
  // a Surprise of this hero just went off: the "?" bloats up and goes poof
  const snap = (player && player.perks || []).map((x) => x.id + ":" + (x.revealed ? 1 : 0));
  const prevSnap = useRef(null);
  useEffect(() => {
    const before = prevSnap.current;
    prevSnap.current = snap;
    if (!before) return;
    const perks = player.perks || [];
    const sprung = perks.some((x, i) => before[i] && before[i].endsWith(":0") && x.revealed && PERK_BY_ID[x.id] && PERK_BY_ID[x.id].surprise);
    if (sprung && lastRect.current) setPoof({ key: Date.now(), rect: lastRect.current });
  }, [snap.join("|")]);
  useEffect(() => {
    if (!poof) return undefined;
    const t = setTimeout(() => setPoof(null), 2300);
    return () => clearTimeout(t);
  }, [poof ? poof.key : null]);
  useEffect(() => { if (ref.current) lastRect.current = ref.current.getBoundingClientRect(); });
  useEffect(() => {
    if (!tip || !tip.pinned) { setSel(null); return undefined; }
    const away = (e) => { const t = e.target; if (!((ref.current && ref.current.contains(t)) || (t.closest && t.closest(".sx-tip")))) { setTip(null); setSel(null); } };
    document.addEventListener("pointerdown", away, true);
    return () => document.removeEventListener("pointerdown", away, true);
  }, [tip && tip.pinned]);
  const fac = dxFaction(player.hero);
  const poofEl = poof ? <SurprisePoof key={poof.key} rect={poof.rect} color={fac.c} dark={fac.dark || "#111"} /> : null;
  if (!list.length) return poofEl;
  const show = (e, pinned) => setTip({ rect: e.currentTarget.getBoundingClientRect(), pinned });
  let bubble = null;
  if (tip) {
    const W = Math.min(310, window.innerWidth - 16);
    const left = Math.max(8, Math.min(window.innerWidth - W - 8, tip.rect.left + tip.rect.width / 2 - W / 2));
    const below = tip.rect.top < 220;
    bubble = createPortal(
      <div className="sx-tip" data-kwtap="1" onClick={(e) => e.stopPropagation()}
        style={{ position: "fixed", left, width: W, boxSizing: "border-box", zIndex: 950, ...(below ? { top: tip.rect.bottom + 8 } : { bottom: window.innerHeight - tip.rect.top + 8 }),
          padding: "10px 12px", borderRadius: pixel ? 0 : 10, border: `2px solid ${fac.c}`, textAlign: "left", lineHeight: 1.35, fontSize: 13,
          background: themed ? "rgba(14,12,10,0.97)" : "#fff", color: themed ? "#efe7d8" : "#111", boxShadow: "0 10px 26px rgba(0,0,0,0.55)",
          fontFamily: themed ? (pixel ? DX_PIXEL_FONT : DX_FONT) : FONT, pointerEvents: tip.pinned ? "auto" : "none" }}>
        <div style={{ fontWeight: 900, marginBottom: 6, color: themed ? fac.c : "#111" }}>
          {owner ? tr("Your Surprises") : tr("Surprises: {n}", { n: list.length, count: list.length })}
        </div>
        {list.map((x, i) => {
          const def = PERK_BY_ID[x.id];
          const isItem = def.level === "item";
          const col = PERK_COLORS[def.level];
          const known = owner || x.revealed;
          const kind = isItem ? tr("Surprise card") : tr("Surprise perk · Level {n}", { n: def.level });
          const rowStyle = isItem
            ? { background: "#000", color: "#fff", border: "1px solid #fff" }
            : { background: themed ? col.row : `color-mix(in srgb, ${col.c} 14%, #fff)`, color: themed ? col.c : "#111", border: `1px solid ${col.c}` };
          return (
            <div key={i} role={known ? "button" : undefined} tabIndex={known ? 0 : undefined}
              onClick={known ? (e) => { e.stopPropagation(); const rect = e.currentTarget.getBoundingClientRect(); setSel((s) => (s && s.i === i ? null : { i, rect })); } : undefined}
              onKeyDown={known ? (e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); const rect = e.currentTarget.getBoundingClientRect(); setSel((s) => (s && s.i === i ? null : { i, rect })); } } : undefined}
              style={{ ...rowStyle, display: "flex", gap: 8, alignItems: "center", padding: "6px 8px", marginTop: 5, borderRadius: pixel ? 0 : 6, cursor: known ? "pointer" : "default", outline: sel && sel.i === i ? `2px solid ${isItem ? "#fff" : col.c}` : undefined }}>
              <PerkIcon level={def.level} surprise size={20} />
              <div style={{ minWidth: 0 }}>
                <div style={{ fontWeight: 800, fontSize: 12.5 }}>{known ? perkNameL(def) : kind}</div>
                <div style={{ fontSize: 11.5, opacity: 0.85 }}>{known ? kind + (owner || x.revealed ? " · " + perkTimeLeft(x) : "") : tr("Hidden")}</div>
              </div>
              {known && <span aria-hidden="true" style={{ marginLeft: "auto", flexShrink: 0, width: 16, height: 16, borderRadius: pixel ? 0 : "50%", border: "1.5px solid currentColor", display: "inline-flex", alignItems: "center", justifyContent: "center", fontSize: 10, fontWeight: 900, fontStyle: "italic", fontFamily: "Georgia, serif", opacity: 0.85 }}>i</span>}
            </div>
          );
        })}
      </div>,
      document.body
    );
  }
  let detail = null;
  const sx = sel && tip && tip.pinned && list[sel.i];
  const sdef = sx && PERK_BY_ID[sx.id];
  if (sdef && (owner || sx.revealed)) {
    const col = PERK_COLORS[sdef.level] || PERK_COLORS[1];
    const edge = sdef.level === "item" ? "#fff" : col.c;
    const W = Math.min(280, window.innerWidth - 16);
    const left = Math.max(8, Math.min(window.innerWidth - W - 8, sel.rect.left + sel.rect.width / 2 - W / 2));
    const below = sel.rect.bottom + 150 < window.innerHeight;
    detail = createPortal(
      <div className="sx-tip sx-detail" data-kwtap="1" onClick={(e) => e.stopPropagation()}
        style={{ position: "fixed", left, width: W, boxSizing: "border-box", zIndex: 960, ...(below ? { top: sel.rect.bottom + 6 } : { bottom: window.innerHeight - sel.rect.top + 6 }),
          padding: "10px 12px", borderRadius: pixel ? 0 : 10, border: `2px solid ${edge}`, textAlign: "left", lineHeight: 1.4, fontSize: 13,
          background: themed ? "rgba(10,9,8,0.98)" : "#fff", color: themed ? "#efe7d8" : "#111", boxShadow: `0 10px 26px rgba(0,0,0,0.6)${themed && !pixel ? `, 0 0 14px ${col.glow || "transparent"}` : ""}`,
          fontFamily: themed ? (pixel ? DX_PIXEL_FONT : DX_FONT) : FONT }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6 }}>
          <PerkIcon level={sdef.level} surprise size={20} />
          <div style={{ fontWeight: 900, color: themed ? edge : "#111", flex: 1, minWidth: 0 }}>{perkNameL(sdef)}</div>
          <button type="button" aria-label={tr("Close")} onClick={(e) => { e.stopPropagation(); setSel(null); }}
            style={{ border: "none", background: "transparent", color: "inherit", font: "inherit", fontSize: 16, lineHeight: 1, cursor: "pointer", padding: 2, opacity: 0.7 }}>×</button>
        </div>
        <div style={{ fontSize: 13 }}><PerkDesc def={sdef} dark={themed} /></div>
        <div style={{ fontSize: 11.5, opacity: 0.7, marginTop: 6 }}>{perkTimeLeft(sx)}</div>
      </div>,
      document.body
    );
  }
  const count = list.length;
  return (
    <span ref={ref} className="sx-badge" style={{ display: "inline-flex", position: "relative", cursor: "help", flexShrink: 0, ...style }}
      onMouseEnter={(e) => { if (!(tip && tip.pinned)) show(e, false); }}
      onMouseLeave={() => setTip((t) => (t && !t.pinned ? null : t))}
      onPointerDown={(e) => e.stopPropagation()}
      onClick={(e) => { e.stopPropagation(); e.preventDefault(); if (tip && tip.pinned) setTip(null); else show(e, true); }}>
      <svg viewBox="-12 -12 24 24" width={size} height={size} style={{ display: "block", filter: themed ? `drop-shadow(0 0 5px ${fac.c})` : undefined }}>
        <circle r="10.8" fill={themed ? fac.dark || "#111" : "#fff"} stroke={fac.c} strokeWidth="2.4" />
        <text x="0" y="5.4" textAnchor="middle" fontSize="15.5" fontWeight="900" fill={fac.c} fontFamily="Arial, sans-serif">?</text>
      </svg>
      {poofEl}
      {count > 1 && <span style={{ position: "absolute", right: -5, bottom: -4, minWidth: 13, height: 13, borderRadius: 7, background: "#000", color: "#fff", border: `1px solid ${fac.c}`, font: "900 9px/11px system-ui, sans-serif", textAlign: "center", padding: "0 2px", boxSizing: "border-box" }}>{count}</span>}
      {bubble}
      {detail}
    </span>
  );
}

/* =========================================================================
   CARD EVENTS — both players see a short animation when a minion is
   destroyed, switches sides, a card is destroyed in a hand, or a drawn card
   burns because the hand is full. The engine records them in state.cardFx.
   ========================================================================= */
function cardFx(state, ev) {
  const clean = { kind: ev.kind, owner: ev.owner, cardId: ev.cardId || null, name: ev.name || null, atk: ev.atk == null ? null : ev.atk, hp: ev.hp == null ? null : ev.hp };
  state.cardFx = [...(state.cardFx || []).slice(-11), { ...clean, id: Date.now().toString(36) + Math.random().toString(36).slice(2, 7) }];
}
const CFX_CSS = `
.cfx-back { position: fixed; inset: 0; z-index: 345; pointer-events: none; display: flex; align-items: center; justify-content: center; flex-direction: column; }
.cfx-dim { position: absolute; inset: 0; background: radial-gradient(ellipse at center, rgba(0,0,0,0.6), rgba(0,0,0,0.15) 70%); animation: cfxDim var(--T) ease both; }
@keyframes cfxDim { 0% { opacity: 0; } 10%, 85% { opacity: 1; } 100% { opacity: 0; } }
.cfx-title { position: relative; font-weight: 900; text-transform: uppercase; letter-spacing: 0.08em; font-size: clamp(20px, 4vw, 32px); color: #fff; padding: 6px 18px; border-radius: 8px; animation: cfxTitle var(--T) ease both; text-shadow: 0 2px 6px rgba(0,0,0,0.8); }
.cfx-sub { position: relative; font-size: 14px; color: #f3ecdf; margin-top: 2px; animation: cfxTitle var(--T) ease both; text-shadow: 0 1px 4px rgba(0,0,0,0.9); }
@keyframes cfxTitle { 0% { opacity: 0; transform: translateY(-14px); } 10%, 82% { opacity: 1; transform: none; } 100% { opacity: 0; } }
.cfx-row { position: relative; display: flex; gap: 14px; margin-top: 14px; }
.cfx-card { position: relative; animation: cfxIn 0.5s cubic-bezier(.2,.8,.2,1) both; }
.cfx-card.flip { animation: cfxFlip 0.8s cubic-bezier(.2,.8,.2,1) both; }
@keyframes cfxIn { 0% { opacity: 0; transform: translateY(var(--fromY, 80px)) scale(0.5); } 100% { opacity: 1; transform: none; } }
@keyframes cfxFlip { 0% { opacity: 0; transform: translateY(var(--fromY, 80px)) scale(0.4) rotateY(180deg); filter: brightness(0); } 60% { filter: brightness(1.6); } 100% { opacity: 1; transform: none; filter: none; } }
.cfx-card.out-move > .cfx-inner { animation: cfxMove 0.9s cubic-bezier(.5,0,.4,1) var(--hold) both; }
@keyframes cfxMove { 0% { transform: none; opacity: 1; } 100% { transform: translateY(var(--toY)) scale(0.6); opacity: 0; } }
.cfx-piece { position: absolute; inset: 0; animation: cfxShow 0.01s linear var(--hold) both, cfxShard 0.9s cubic-bezier(.45,0,.8,.6) var(--hold) both; }
@keyframes cfxShow { from { visibility: hidden; } to { visibility: visible; } }
@keyframes cfxShard { 0% { transform: none; opacity: 1; filter: none; } 10% { filter: brightness(2.4); } 100% { transform: translate(var(--sx), var(--sy)) rotate(var(--sr)) scale(0.7); opacity: 0; filter: brightness(0.6) grayscale(0.7); } }
.cfx-card .cfx-whole { animation: cfxHide 0.05s linear var(--hold) forwards; }
@keyframes cfxHide { from { opacity: 1; } to { opacity: 0; } }
.cfx-flash { position: absolute; left: 50%; top: 50%; width: 10px; height: 10px; margin: -5px; border-radius: 50%; background: radial-gradient(circle, #fff, rgba(255,170,80,0.7) 40%, rgba(255,80,20,0) 70%); animation: cfxFlash 0.6s ease-out var(--hold) both; }
@keyframes cfxFlash { 0% { transform: scale(0); opacity: 0; } 15% { opacity: 1; } 100% { transform: scale(30); opacity: 0; } }
.cfx-token { width: 150px; height: 200px; border-radius: 12px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; background: linear-gradient(160deg, #3a332b, #14110e); border: 3px solid #8a7a60; color: #fff; font-weight: 900; text-align: center; padding: 8px; box-sizing: border-box; }
.cfx-token.np { background: #fff; color: #111; border: 3px solid #000; }
`;
if (typeof document !== "undefined" && !document.getElementById("cfx-css")) {
  const st = document.createElement("style");
  st.id = "cfx-css";
  st.textContent = CFX_CSS;
  document.head.appendChild(st);
}
const CFX_SHARDS = [
  { clip: "polygon(0 0, 55% 0, 40% 45%, 0 35%)", sx: "-160px", sy: "-90px", sr: "-40deg" },
  { clip: "polygon(55% 0, 100% 0, 100% 40%, 40% 45%)", sx: "170px", sy: "-110px", sr: "35deg" },
  { clip: "polygon(0 35%, 40% 45%, 30% 75%, 0 70%)", sx: "-200px", sy: "60px", sr: "-60deg" },
  { clip: "polygon(40% 45%, 100% 40%, 100% 72%, 62% 68%)", sx: "210px", sy: "70px", sr: "50deg" },
  { clip: "polygon(30% 75%, 40% 45%, 62% 68%, 55% 100%, 20% 100%)", sx: "-40px", sy: "220px", sr: "25deg" },
  { clip: "polygon(0 70%, 30% 75%, 20% 100%, 0 100%)", sx: "-130px", sy: "200px", sr: "-75deg" },
  { clip: "polygon(62% 68%, 100% 72%, 100% 100%, 55% 100%)", sx: "120px", sy: "230px", sr: "70deg" },
];
function CfxFace({ ev, themed, sc }) {
  const c = ev.cardId ? findCard(ev.cardId) : null;
  if (c) return themed ? <DeluxeCard card={c} scale={sc} /> : <div style={{ transform: "scale(1.15)", margin: 10 }}><MiniCard cardId={c.id} /></div>;
  return (
    <div className={"cfx-token" + (themed ? "" : " np")} style={themed ? { width: DX_CARD_W * sc, height: DX_CARD_H * sc } : undefined}>
      <div style={{ fontSize: 17 }}>{cardNameL(ev.name || "")}</div>
      {ev.atk != null && <div style={{ fontSize: 22 }}><span style={{ color: "#ffb03a" }}>{ev.atk}</span> / <span style={{ color: "#ff5a48" }}>{ev.hp}</span></div>}
    </div>
  );
}
const CFX_TIME = { destroyed: 2900, moved: 2700, handDestroyed: 3700, burned: 3400 };
function CardFxHost({ state, myIdx }) {
  const list = state.cardFx || [];
  const seen = useRef(null);
  const [queue, setQueue] = useState([]);
  const mode = useDisplay().mode;
  const themed = isThemedMode(mode);
  const ids = list.map((e) => e.id).join(",");
  useEffect(() => {
    if (!seen.current) { seen.current = new Set(list.map((e) => e.id)); return; }
    // on the illustrated tables a minion that switches sides glides across the board instead (see dxSlideAcross)
    const fresh = list.filter((e) => !seen.current.has(e.id) && !(themed && e.kind === "moved"));
    list.forEach((e) => seen.current.add(e.id));
    if (!fresh.length) return;
    const groups = [];
    fresh.forEach((e) => {
      const g = groups.find((x) => x.kind === e.kind && x.owner === e.owner);
      if (g && g.items.length < 6) g.items.push(e); else groups.push({ key: e.id, kind: e.kind, owner: e.owner, items: [e] });
    });
    setQueue((q) => [...q, ...groups].slice(-6));
  }, [ids]);
  const cur = queue[0];
  useEffect(() => {
    if (!cur) return undefined;
    const t = setTimeout(() => setQueue((q) => q.slice(1)), CFX_TIME[cur.kind] || 2800);
    return () => clearTimeout(t);
  }, [cur && cur.key]);
  if (!cur) return null;
  const T = CFX_TIME[cur.kind] || 2800;
  const mine = cur.owner === myIdx;
  const n = cur.items.length;
  const vw = window.innerWidth, vh = window.innerHeight;
  const sc = Math.max(0.3, Math.min(0.85, (vw - 40) / n / (DX_CARD_W + 14), (vh * 0.55) / DX_CARD_H));
  const hold = cur.kind === "handDestroyed" ? 2.3 : cur.kind === "burned" ? 2.0 : 1.5;
  const shatter = cur.kind !== "moved";
  const title = {
    destroyed: n > 1 ? tr("Minions destroyed!") : tr("Minion destroyed!"),
    moved: tr("Switched sides!"),
    handDestroyed: tr("Destroyed in hand!"),
    burned: tr("Hand full — card burned!"),
  }[cur.kind];
  const sub = cur.kind === "moved"
    ? (mine ? tr("Now on your side") : tr("Now on your opponent's side"))
    : cur.kind === "burned" ? (mine ? tr("You drew it with 10 cards in your hand.") : tr("Your opponent drew it with 10 cards in their hand."))
    : mine ? tr("Your card") : tr("Your opponent's card");
  const titleBg = cur.kind === "moved" ? "linear-gradient(90deg,#1a4c8a,#2f7fd6)" : "linear-gradient(90deg,#8a1a10,#d2381f)";
  // where the card comes from / goes to: your side is below, the enemy's above
  const fromY = cur.kind === "moved" ? (mine ? "-160px" : "160px") : (mine ? "160px" : "-160px");
  const toY = mine ? "200px" : "-200px";
  return createPortal(
    <div key={cur.key} className="cfx-back" style={{ "--T": T + "ms", fontFamily: themed ? DX_FONT : FONT }}>
      <div className="cfx-dim" />
      <div className="cfx-title" style={{ background: titleBg }}>{title}</div>
      <div className="cfx-sub">{sub}</div>
      <div className="cfx-row">
        {cur.items.map((ev, i) => (
          <div key={ev.id} className={"cfx-card" + (cur.kind === "burned" ? " flip" : "") + (shatter ? "" : " out-move")} style={{ "--fromY": fromY, "--toY": toY, "--hold": hold + i * 0.08 + "s", animationDelay: i * 0.08 + "s" }}>
            <div className="cfx-inner" style={{ position: "relative" }}>
              {shatter ? (
                <>
                  <div className="cfx-whole"><CfxFace ev={ev} themed={themed} sc={sc} /></div>
                  {CFX_SHARDS.map((sh, k) => (
                    <div key={k} className="cfx-piece" style={{ clipPath: sh.clip, WebkitClipPath: sh.clip, "--sx": sh.sx, "--sy": sh.sy, "--sr": sh.sr }}>
                      <CfxFace ev={ev} themed={themed} sc={sc} />
                    </div>
                  ))}
                  <div className="cfx-flash" />
                </>
              ) : <CfxFace ev={ev} themed={themed} sc={sc} />}
            </div>
          </div>
        ))}
      </div>
    </div>,
    document.body
  );
}

// The "?" over the hero bloats up and bursts into a puff of smoke that reveals "SURPRISE!"
const POOF_CSS = `
.sx-poof { position: fixed; z-index: 960; pointer-events: none; width: 0; height: 0; }
.sx-poof .q { position: absolute; left: -16px; top: -16px; width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center;
  font: 900 22px/1 Arial, sans-serif; animation: sxBloat 0.75s cubic-bezier(.3,.6,.4,1.4) both; }
@keyframes sxBloat { 0% { transform: scale(1); } 35% { transform: scale(1.5) rotate(-8deg); } 55% { transform: scale(1.3) rotate(6deg); } 80% { transform: scale(2.4); opacity: 1; } 100% { transform: scale(2.8); opacity: 0; } }
.sx-poof .puff { position: absolute; left: -22px; top: -22px; width: 44px; height: 44px; border-radius: 50%; opacity: 0;
  background: radial-gradient(circle at 40% 35%, rgba(255,255,255,0.95), rgba(220,220,220,0.75) 45%, rgba(160,160,160,0) 72%);
  animation: sxPuff 1.1s ease-out 0.6s both; }
@keyframes sxPuff { 0% { opacity: 0; transform: translate(0,0) scale(0.3); } 20% { opacity: 1; } 100% { opacity: 0; transform: translate(var(--px), var(--py)) scale(var(--ps)); } }
.sx-poof .word { position: absolute; left: 0; top: -6px; transform: translate(-50%,-50%); white-space: nowrap; font: 900 30px/1 system-ui, -apple-system, "Segoe UI", sans-serif;
  letter-spacing: 0.06em; color: #fff; -webkit-text-stroke: 1.5px rgba(0,0,0,0.6); animation: sxWord 1.7s cubic-bezier(.2,.9,.3,1.3) 0.62s both; }
.sx-poof.down .word { animation-name: sxWordDown; top: 10px; }
@keyframes sxWordDown { 0% { opacity: 0; transform: translate(-50%,-50%) scale(0.2) rotate(-12deg); } 22% { opacity: 1; transform: translate(-50%,10%) scale(1.25) rotate(4deg); }
  38% { transform: translate(-50%,20%) scale(1) rotate(-2deg); } 78% { opacity: 1; transform: translate(-50%,40%) scale(1); } 100% { opacity: 0; transform: translate(-50%,70%) scale(0.95); } }
@keyframes sxWord { 0% { opacity: 0; transform: translate(-50%,-50%) scale(0.2) rotate(-12deg); } 22% { opacity: 1; transform: translate(-50%,-90%) scale(1.25) rotate(4deg); }
  38% { transform: translate(-50%,-95%) scale(1) rotate(-2deg); } 78% { opacity: 1; transform: translate(-50%,-110%) scale(1); } 100% { opacity: 0; transform: translate(-50%,-140%) scale(0.95); } }
`;
if (typeof document !== "undefined" && !document.getElementById("sx-poof-css")) {
  const st = document.createElement("style");
  st.id = "sx-poof-css";
  st.textContent = POOF_CSS;
  document.head.appendChild(st);
}
const POOF_PUFFS = Array.from({ length: 9 }, (_, i) => { const a = (i / 9) * Math.PI * 2 + 0.3; return { px: Math.round(Math.cos(a) * 46) + "px", py: Math.round(Math.sin(a) * 34 - 6) + "px", ps: (1.4 + (i % 3) * 0.35).toFixed(2) }; });
function SurprisePoof({ rect, color, dark }) {
  const cx = rect.left + rect.width / 2, cy = rect.top + rect.height / 2;
  return createPortal(
    <div className={"sx-poof" + (cy < 140 ? " down" : "")} style={{ left: Math.max(110, Math.min(window.innerWidth - 110, cx)), top: cy }}>
      {POOF_PUFFS.map((p, i) => <i key={i} className="puff" style={{ "--px": p.px, "--py": p.py, "--ps": p.ps, animationDelay: 0.6 + (i % 3) * 0.05 + "s" }} />)}
      <div className="q" style={{ background: dark, border: `3px solid ${color}`, color, boxShadow: `0 0 16px ${color}` }}>?</div>
      <div className="word" style={{ textShadow: `0 0 12px ${color}, 0 0 26px ${color}, 0 3px 0 rgba(0,0,0,0.5)` }}>{tr("SURPRISE!")}</div>
    </div>,
    document.body
  );
}

/* =========================================================================
   BALANCE PASS helpers: hand costs that change during a match, Compass and
   Chosen John.
   ========================================================================= */
// Scrap Golem: 2 less per minion on the board (both sides). Cyber-Golem: 1 less per own turn it waited in the hand.
function dynMinionCost(state, p, card, handIdx) {
  let cost = card.cost;
  if (card.costPerMinion && state) cost -= card.costPerMinion * state.players.reduce((n, pl) => n + pl.board.filter((m) => m.hp > 0).length, 0);
  if (card.ageDiscount && p && handIdx != null) cost -= card.ageDiscount * handAgeOf(p, card.id, handIdx);
  return Math.max(0, cost);
}
// what the cost gem on a hand card shows ("1+4" for items, the lowered cost for those two minions)
function handCostLabel(state, p, card, handIdx) {
  if (card.type === "spell") return itemCostLabel(p, card);
  const c = dynMinionCost(state, p, card, handIdx);
  return c !== card.cost ? String(c) : null;
}
// blue stroke when a card in the hand costs less than usual, red when it costs more (crippled hands make items dearer)
function handCostTone(state, p, card, handIdx) {
  if (!card) return null;
  if (card.type === "spell") return p && crippledCount(p) > 0 ? "up" : null;
  const c = dynMinionCost(state, p, card, handIdx);
  return c < card.cost ? "down" : c > card.cost ? "up" : null;
}
