// ---------- Terms of Use + Privacy Policy ----------
// Version of the documents in public/terms.html and public/privacy.html. New accounts send it to
// claimFirstHero, which refuses to create an account without it. Existing players are never asked again.
const TERMS_VERSION = "2026-10-17";
const TERMS_URL = "/terms.html", PRIVACY_URL = "/privacy.html";
const _terms = { ok: (() => { try { return sessionStorage.getItem("ab_terms") === TERMS_VERSION; } catch (e) { return false; } })() }, _termsSubs = new Set();
function setTermsOk(v) {
  _terms.ok = !!v;
  try { if (v) sessionStorage.setItem("ab_terms", TERMS_VERSION); else sessionStorage.removeItem("ab_terms"); } catch (e) {}
  _termsSubs.forEach((f) => f());
}
function useTermsOk() {
  const [, bump] = useState(0);
  useEffect(() => { const f = () => bump((n) => n + 1); _termsSubs.add(f); return () => { _termsSubs.delete(f); }; }, []);
  return _terms.ok;
}
// a translated sentence with {terms} and {privacy} turned into links
function LegalText({ text }) {
  const link = (href, label) => <a key={href} href={href} target="_blank" rel="noopener" onClick={(e) => e.stopPropagation()} style={{ color: "inherit", textDecoration: "underline", fontWeight: 700 }}>{label}</a>;
  // the words in [brackets] become the links: the first one to the Terms, the second to the Privacy Policy
  let n = 0;
  return <>{String(text).split(/(\[[^\]]+\])/).map((p, i) => /^\[.*\]$/.test(p) ? link(n++ === 0 ? TERMS_URL : PRIVACY_URL, p.slice(1, -1)) : <React.Fragment key={i}>{p}</React.Fragment>)}</>;
}
function TermsCheck({ style, note }) {
  const ok = useTermsOk();
  return (
    <label className="ab-terms" style={{ display: "flex", gap: 10, alignItems: "flex-start", textAlign: "left", fontSize: 13, lineHeight: 1.45, cursor: "pointer", ...style }}>
      <input type="checkbox" checked={ok} onChange={(e) => setTermsOk(e.target.checked)} style={{ width: 18, height: 18, marginTop: 1, flex: "none", accentColor: "#e8782a", cursor: "pointer" }} />
      <span><LegalText text={tr("I agree to the [Terms of Use] and the [Privacy Policy].")} />{note ? <span style={{ display: "block", opacity: 0.7, fontSize: 12 }}>{note}</span> : null}</span>
    </label>
  );
}
